/**
 * Policy Clause Templates — Incident Management (p30-p33)
 * Based on ISO 27001:2022, BSI IT-Grundschutz, NIST CSF 2.0, NIS2 Art.21
 */
import type { PolicyClause } from "../policyClauseTemplates";

export const incidentManagementClauses: Record<string, PolicyClause[]> = {

  // ═══════════════════════════════════════════════════════════════
  // P30 — Incident Response Policy
  // ═══════════════════════════════════════════════════════════════
  p30: [
    { id: "p30-c00", title: "Zweck und Geltungsbereich der Incident-Response-Richtlinie", titleEn: "Purpose & Scope of Incident Response Policy",
      description: "Diese Richtlinie definiert den Rahmen für die Erkennung, Meldung, Bewertung, Eindämmung, Behebung und Nachbereitung von Sicherheitsvorfällen. Sie gilt für alle Mitarbeitenden, Auftragnehmer und Dritte mit Zugang zu den Informationssystemen der Organisation. Die Richtlinie stellt sicher, dass Vorfälle systematisch, effizient und in Übereinstimmung mit regulatorischen Anforderungen (insbesondere NIS2) behandelt werden.",
      descriptionEn: "This policy defines the framework for detection, reporting, assessment, containment, remediation, and post-incident review of security incidents. It applies to all employees, contractors, and third parties with access to the organisation's information systems. The policy ensures incidents are handled systematically, efficiently, and in compliance with regulatory requirements (especially NIS2).",
      reason: "Ohne einen strukturierten Incident-Response-Rahmen werden Vorfälle ad-hoc und inkonsistent behandelt, was den Schaden vergrößert und regulatorische Anforderungen gefährdet.",
      reasonEn: "Without a structured incident response framework, incidents are handled ad-hoc and inconsistently, increasing damage and jeopardising regulatory requirements.",
      whenRequired: "Immer erforderlich als Grundlage des Vorfallmanagements.",
      whenRequiredEn: "Always required as the foundation of incident management.",
      sources: ["ISO 27001:2022 A.5.24-A.5.28", "NIS2 Art.21(2)(b), Art.23", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS"] },

    { id: "p30-c01", title: "Incident-Response-Team (IRT/CSIRT) Zusammensetzung", titleEn: "Incident Response Team (IRT/CSIRT) Composition",
      description: "Wir müssen ein Incident-Response-Team (IRT) oder Computer Security Incident Response Team (CSIRT) mit klaren Rollen und Verantwortlichkeiten einrichten. Das Team muss mindestens umfassen: Incident Manager (Gesamtkoordination), technische Analysten, forensische Spezialisten, Kommunikationsverantwortliche und Rechtsberater. Stellvertretungsregelungen und 24/7-Erreichbarkeit für kritische Vorfälle müssen sichergestellt sein.",
      descriptionEn: "We must establish an Incident Response Team (IRT) or Computer Security Incident Response Team (CSIRT) with clear roles and responsibilities. The team must include at minimum: Incident Manager (overall coordination), technical analysts, forensic specialists, communications officers, and legal advisors. Deputy arrangements and 24/7 availability for critical incidents must be ensured.",
      reason: "Effektive Incident Response erfordert ein interdisziplinäres Team mit klar definierten Rollen. Ohne vorab festgelegte Teamstruktur geht wertvolle Zeit bei der Koordination verloren.",
      reasonEn: "Effective incident response requires an interdisciplinary team with clearly defined roles. Without pre-established team structure, valuable time is lost in coordination.",
      whenRequired: "Immer erforderlich, unabhängig von der Organisationsgröße.",
      whenRequiredEn: "Always required, regardless of organisation size.",
      sources: ["ISO 27001:2022 A.5.24", "NIS2 Art.21(2)(b)", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.MA"] },

    { id: "p30-c02", title: "Incident-Response-Phasen und Prozess", titleEn: "Incident Response Phases & Process",
      description: "Der Incident-Response-Prozess muss folgende Phasen umfassen: 1) Vorbereitung (Werkzeuge, Schulungen, Playbooks), 2) Erkennung & Analyse (Triage, Schweregradbewertung), 3) Eindämmung (kurzfristige und langfristige Maßnahmen), 4) Bereinigung (Entfernung der Bedrohung, Systemsäuberung), 5) Wiederherstellung (Rückkehr zum Normalbetrieb), 6) Nachbereitung (Lessons Learned, Prozessverbesserung). Für jede Phase müssen Verantwortlichkeiten, Aktivitäten und Dokumentationsanforderungen definiert sein.",
      descriptionEn: "The incident response process must include the following phases: 1) Preparation (tools, training, playbooks), 2) Detection & Analysis (triage, severity assessment), 3) Containment (short-term and long-term measures), 4) Eradication (threat removal, system cleanup), 5) Recovery (return to normal operations), 6) Post-Incident (lessons learned, process improvement). For each phase, responsibilities, activities, and documentation requirements must be defined.",
      reason: "Ein strukturierter Prozess stellt sicher, dass keine kritischen Schritte übersprungen werden und die Vorfallbehandlung effizient und nachvollziehbar erfolgt.",
      reasonEn: "A structured process ensures no critical steps are skipped and incident handling is efficient and traceable.",
      whenRequired: "Immer erforderlich als Kernprozess des Vorfallmanagements.",
      whenRequiredEn: "Always required as the core process of incident management.",
      sources: ["ISO 27001:2022 A.5.26", "NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS"] },

    { id: "p30-c03", title: "Eindämmungsstrategien nach Vorfalltyp", titleEn: "Containment Strategies by Incident Type",
      description: "Für verschiedene Vorfalltypen müssen vordefinierte Eindämmungsstrategien dokumentiert sein: Ransomware (sofortige Netzwerkisolierung betroffener Systeme), Datenleck (Sperren des betroffenen Zugangs, Änderung von Credentials), DDoS (Aktivierung von DDoS-Mitigation, Traffic-Umleitung), Insider-Bedrohung (Entzug der Berechtigungen, Beweissicherung), Phishing (Blockierung der Absenderdomain, Quarantäne betroffener Postfächer). Die Strategien müssen die Balance zwischen Schadensbegrenzung und Beweissicherung berücksichtigen.",
      descriptionEn: "Pre-defined containment strategies must be documented for different incident types: Ransomware (immediate network isolation of affected systems), data breach (locking affected access, credential changes), DDoS (activating DDoS mitigation, traffic rerouting), insider threat (revoking permissions, evidence preservation), phishing (blocking sender domain, quarantining affected mailboxes). Strategies must balance damage limitation with evidence preservation.",
      reason: "Allgemeine Eindämmungsstrategien funktionieren nicht für alle Vorfalltypen gleich. Vordefinierte, typspezifische Strategien ermöglichen schnellere und effektivere Reaktion.",
      reasonEn: "General containment strategies do not work equally for all incident types. Pre-defined, type-specific strategies enable faster and more effective response.",
      whenRequired: "Erforderlich für alle Vorfalltypen, die in der Organisation auftreten können.",
      whenRequiredEn: "Required for all incident types that may occur in the organisation.",
      sources: ["NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1", "ISO 27001:2022 A.5.26"] },

    { id: "p30-c04", title: "Incident-Response-Playbooks", titleEn: "Incident Response Playbooks",
      description: "Wir müssen detaillierte Playbooks für die häufigsten und kritischsten Vorfallszenarien erstellen. Mindest-Playbooks umfassen: Ransomware-Angriff, Datenpanne/Datenexfiltration, kompromittiertes Benutzerkonto, Malware-Infektion, DDoS-Angriff, Insider-Bedrohung, Phishing-Kampagne und Lieferketten-Kompromittierung. Playbooks müssen Schritt-für-Schritt-Anweisungen, Entscheidungsbäume, Kontaktlisten und Checklisten enthalten.",
      descriptionEn: "We must create detailed playbooks for the most common and critical incident scenarios. Minimum playbooks include: ransomware attack, data breach/exfiltration, compromised user account, malware infection, DDoS attack, insider threat, phishing campaign, and supply chain compromise. Playbooks must contain step-by-step instructions, decision trees, contact lists, and checklists.",
      reason: "Unter dem Druck eines laufenden Vorfalls werden ohne Playbooks wichtige Schritte vergessen oder falsche Entscheidungen getroffen. Playbooks standardisieren die Reaktion und beschleunigen die Bearbeitung.",
      reasonEn: "Under the pressure of an ongoing incident, important steps are forgotten or wrong decisions are made without playbooks. Playbooks standardise response and accelerate handling.",
      whenRequired: "Erforderlich für alle Organisationen mit Incident-Response-Fähigkeiten.",
      whenRequiredEn: "Required for all organisations with incident response capabilities.",
      sources: ["NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1", "ISO 27001:2022 A.5.24", "NIST CSF 2.0 RS.RP"] },

    { id: "p30-c05", title: "Forensische Beweissicherung", titleEn: "Forensic Evidence Preservation",
      description: "Bei jedem Sicherheitsvorfall müssen forensische Beweise nach anerkannten Standards gesichert werden. Die Chain of Custody (Beweiskette) muss lückenlos dokumentiert werden. Forensische Images müssen vor der Bereinigung erstellt werden. Flüchtige Daten (RAM, Netzwerkverbindungen, laufende Prozesse) müssen vor dem Herunterfahren gesichert werden. Hash-Werte müssen für alle sichergestellten Beweise erstellt und dokumentiert werden.",
      descriptionEn: "For every security incident, forensic evidence must be preserved according to recognised standards. The chain of custody must be documented without gaps. Forensic images must be created before cleanup. Volatile data (RAM, network connections, running processes) must be captured before shutdown. Hash values must be created and documented for all preserved evidence.",
      reason: "Ohne ordnungsgemäße Beweissicherung sind spätere forensische Analysen, strafrechtliche Verfolgung und Versicherungsansprüche gefährdet. Die Beweiskette muss gerichtsfest sein.",
      reasonEn: "Without proper evidence preservation, later forensic analyses, criminal prosecution, and insurance claims are jeopardised. The chain of custody must be court-admissible.",
      whenRequired: "Erforderlich bei allen Vorfällen, die forensische Analyse erfordern könnten.",
      whenRequiredEn: "Required for all incidents that may require forensic analysis.",
      sources: ["ISO 27001:2022 A.5.28", "BSI IT-Grundschutz DER.2.2", "NIST SP 800-86", "NIST CSF 2.0 RS.AN"] },

    { id: "p30-c06", title: "Strategische Krisenkommunikation und Entscheidungsrahmen", titleEn: "Strategic Crisis Communication & Decision Framework",
      description: "Wir müssen einen strategischen Krisenkommunikationsplan definieren, der die Entscheidungsbefugnisse für externe Kommunikation (Medien, Öffentlichkeit, Regulierungsbehörden) regelt. Der Incident Manager koordiniert sämtliche Kommunikation; ein designierter Sprecher muss vorab benannt sein. Der Plan muss Schwellenwerte definieren, ab denen Krisenstab, Vorstand und Rechtsabteilung eingebunden werden. Operative Sprachregelungen, Kommunikationsvorlagen und Social-Media-Richtlinien für Vorfälle werden in p31-c19 geregelt.",
      descriptionEn: "We must define a strategic crisis communication plan governing decision authorities for external communication (media, public, regulators). The Incident Manager coordinates all communication; a designated spokesperson must be pre-appointed. The plan must define thresholds for involving crisis team, board, and legal department. Operational talking points, communication templates, and social media guidelines for incidents are governed in p31-c19.",
      reason: "Strategische Kommunikationsentscheidungen — wann, gegenüber wem und in welchem Umfang kommuniziert wird — erfordern vorab definierte Befugnisse, um Reputationsschäden und rechtliche Risiken zu minimieren.",
      reasonEn: "Strategic communication decisions — when, to whom, and to what extent to communicate — require pre-defined authorities to minimise reputational damage and legal risks.",
      whenRequired: "Erforderlich für alle Vorfälle, die interne oder externe Aufmerksamkeit erhalten könnten.",
      whenRequiredEn: "Required for all incidents that could receive internal or external attention.",
      sources: ["ISO 27001:2022 A.5.25", "NIS2 Art.23", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.CO"] },

    { id: "p30-c07", title: "Lessons Learned und Post-Incident-Review", titleEn: "Lessons Learned & Post-Incident Review",
      description: "Nach jedem signifikanten Sicherheitsvorfall muss eine Post-Incident-Review (Lessons-Learned-Sitzung) innerhalb von 10 Arbeitstagen durchgeführt werden. Die Review muss analysieren: Ursache (Root Cause), Erkennungszeit, Reaktionseffektivität, Kommunikationsqualität, was gut funktioniert hat und was verbessert werden muss. Konkrete Verbesserungsmaßnahmen müssen definiert, verantwortlich zugewiesen und terminiert werden. Ergebnisse müssen dokumentiert und der Leitung berichtet werden.",
      descriptionEn: "After every significant security incident, a post-incident review (lessons learned session) must be conducted within 10 business days. The review must analyse: root cause, detection time, response effectiveness, communication quality, what worked well, and what needs improvement. Concrete improvement measures must be defined, assigned responsible owners, and scheduled. Results must be documented and reported to management.",
      reason: "Ohne systematische Nachbereitung wiederholen sich dieselben Fehler. Lessons Learned sind der wichtigste Mechanismus für die kontinuierliche Verbesserung des Vorfallmanagements.",
      reasonEn: "Without systematic post-incident review, the same mistakes are repeated. Lessons learned are the most important mechanism for continuous improvement of incident management.",
      whenRequired: "Erforderlich nach jedem signifikanten Sicherheitsvorfall (Schweregrad hoch oder kritisch).",
      whenRequiredEn: "Required after every significant security incident (high or critical severity).",
      sources: ["ISO 27001:2022 A.5.27", "NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.IM"] },

    { id: "p30-c08", title: "Incident-Response-Übungen und Simulationen", titleEn: "Incident Response Exercises & Simulations",
      description: "Wir müssen regelmäßig Incident-Response-Übungen durchführen, um die Bereitschaft des Teams zu testen und zu verbessern. Tabletop-Übungen müssen mindestens halbjährlich stattfinden, technische Simulationen mindestens jährlich. Übungsszenarien müssen reale Bedrohungen widerspiegeln und verschiedene Vorfalltypen abdecken. Ergebnisse müssen dokumentiert und identifizierte Defizite behoben werden.",
      descriptionEn: "We must regularly conduct incident response exercises to test and improve team readiness. Tabletop exercises must occur at least semi-annually, technical simulations at least annually. Exercise scenarios must reflect real threats and cover various incident types. Results must be documented and identified deficiencies remediated.",
      reason: "Ungetestete Pläne versagen im Ernstfall. Regelmäßige Übungen stellen sicher, dass das Team mit den Prozessen vertraut ist und unter Druck effektiv handeln kann.",
      reasonEn: "Untested plans fail in real situations. Regular exercises ensure the team is familiar with processes and can act effectively under pressure.",
      whenRequired: "NIS2 Art.21(2)(c,e) fordert wirksames Krisen- und Incident-Management ohne feste Übungsfrequenz; halbjährliche Tabletops/jährliche Simulationen sind etablierte Best Practice (BSI IT-Grundschutz DER.4, ISO 27001 A.5.24).",
      whenRequiredEn: "NIS2 Art.21(2)(c,e) requires effective crisis and incident management without specifying an exercise frequency; semi-annual tabletops / annual simulations are established best practice (BSI IT-Grundschutz DER.4, ISO 27001 A.5.24).",
      sources: ["NIS2 Art.21(2)(e)", "ISO 27001:2022 A.5.24", "BSI IT-Grundschutz DER.4", "NIST CSF 2.0 RS.RP"] },

    { id: "p30-c09", title: "Strategische Eskalation und Entscheidungsbefugnisse", titleEn: "Strategic Escalation & Decision Authority",
      description: "Strategische Eskalationsverfahren müssen die Entscheidungsbefugnisse für kritische Maßnahmen definieren: Netzwerkabschaltung, Produktionsunterbrechung, externe Meldung an Aufsichtsbehörden, Strafanzeige und öffentliche Kommunikation. Für jede Eskalationsstufe müssen maximale Zeitrahmen und die befugten Entscheidungsträger (CISO, Geschäftsleitung, Vorstand, Krisenstab) festgelegt sein. Die operative Melde-Eskalationsmatrix (Schweregrad-zu-Kontaktebene-Zuordnung) wird in p31-c07 geregelt.",
      descriptionEn: "Strategic escalation procedures must define decision authorities for critical measures: network shutdown, production interruption, external reporting to authorities, criminal complaint, and public communication. For each escalation level, maximum timeframes and authorised decision-makers (CISO, executive management, board, crisis team) must be defined. The operational reporting escalation matrix (severity-to-contact-level mapping) is governed in p31-c07.",
      reason: "Strategische Entscheidungen wie Netzwerkabschaltung oder Strafanzeige erfordern vorab definierte Befugnisse, da sie unter Zeitdruck nicht ad-hoc verhandelt werden können.",
      reasonEn: "Strategic decisions such as network shutdown or criminal complaint require pre-defined authorities, as they cannot be negotiated ad-hoc under time pressure.",
      whenRequired: "Immer erforderlich als Teil des Incident-Response-Prozesses.",
      whenRequiredEn: "Always required as part of the incident response process.",
      sources: ["ISO 27001:2022 A.5.25", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.MA"] },

    { id: "p30-c10", title: "Werkzeuge und Infrastruktur für Incident Response", titleEn: "Incident Response Tools & Infrastructure",
      description: "Wir müssen die erforderlichen Werkzeuge und Infrastruktur für Incident Response bereitstellen und warten. Dies umfasst: forensische Workstations, Netzwerkanalyse-Tools, Malware-Sandboxen, verschlüsselte Kommunikationskanäle (für den Fall kompromittierter Systeme), ein Incident-Tracking-System und vorbereitete Wiederherstellungsmedien. Werkzeuge müssen regelmäßig aktualisiert und getestet werden.",
      descriptionEn: "We must provide and maintain the required tools and infrastructure for incident response. This includes: forensic workstations, network analysis tools, malware sandboxes, encrypted communication channels (in case of compromised systems), an incident tracking system, and prepared recovery media. Tools must be regularly updated and tested.",
      reason: "Ohne vorbereitete Werkzeuge ist das IRT im Ernstfall handlungsunfähig. Insbesondere verschlüsselte Kommunikation und forensische Fähigkeiten müssen vor einem Vorfall bereitstehen.",
      reasonEn: "Without prepared tools, the IRT is incapable of action in an emergency. Especially encrypted communication and forensic capabilities must be ready before an incident.",
      whenRequired: "Erforderlich für alle Organisationen mit Incident-Response-Fähigkeiten.",
      whenRequiredEn: "Required for all organisations with incident response capabilities.",
      sources: ["ISO 27001:2022 A.5.24", "NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p30-c11", title: "Zusammenarbeit mit Strafverfolgungsbehörden", titleEn: "Cooperation with Law Enforcement",
      description: "Wir müssen Verfahren für die Zusammenarbeit mit Strafverfolgungsbehörden bei Cybersicherheitsvorfällen definieren. Kriterien für die Erstattung einer Strafanzeige müssen festgelegt sein. Kontaktdaten der zuständigen Cybercrime-Einheiten müssen aktuell gehalten werden. Die Beweissicherung muss den Anforderungen für gerichtliche Verwertbarkeit genügen. Rechtliche Beratung muss vor externer Kommunikation eingeholt werden.",
      descriptionEn: "We must define procedures for cooperation with law enforcement in cybersecurity incidents. Criteria for filing criminal complaints must be established. Contact details of relevant cybercrime units must be kept current. Evidence preservation must meet requirements for judicial admissibility. Legal advice must be obtained before external communication.",
      reason: "Die Zusammenarbeit mit Behörden kann entscheidend für die Aufklärung von Vorfällen und die Verhinderung weiterer Angriffe sein. Ohne vordefinierte Verfahren geht wertvolle Zeit verloren.",
      reasonEn: "Cooperation with authorities can be crucial for investigating incidents and preventing further attacks. Without pre-defined procedures, valuable time is lost.",
      whenRequired: "Erforderlich insbesondere bei Vorfällen mit kriminellem Hintergrund oder meldepflichtigen Datenpannen.",
      whenRequiredEn: "Required especially for incidents with criminal background or reportable data breaches.",
      sources: ["NIS2 Art.23", "DSGVO Art.33-34", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.CO"] },

    { id: "p30-c12", title: "Externe Incident-Response-Unterstützung", titleEn: "External Incident Response Support",
      description: "Wir müssen prüfen, ob Retainer-Verträge mit externen Incident-Response-Dienstleistern (IR-Retainer) für den Fall komplexer Vorfälle benötigt werden. Verträge müssen Reaktionszeiten (SLA), Leistungsumfang, Zugangsbedingungen und Vertraulichkeitsvereinbarungen definieren. Externe Experten müssen vorab über die IT-Umgebung informiert werden. Die Integration externer Teams in interne Prozesse muss geregelt sein.",
      descriptionEn: "We must evaluate whether retainer agreements with external incident response providers (IR retainer) are needed for complex incidents. Contracts must define response times (SLA), scope of services, access conditions, and confidentiality agreements. External experts must be briefed on the IT environment in advance. Integration of external teams into internal processes must be regulated.",
      reason: "Nicht jede Organisation kann alle Incident-Response-Kompetenzen intern vorhalten. Externe Retainer stellen sicher, dass bei komplexen Vorfällen schnell spezialisierte Hilfe verfügbar ist.",
      reasonEn: "Not every organisation can maintain all incident response competencies internally. External retainers ensure specialised help is quickly available for complex incidents.",
      whenRequired: "Empfohlen für Organisationen ohne umfassende interne Forensik-Fähigkeiten.",
      whenRequiredEn: "Recommended for organisations without comprehensive internal forensic capabilities.",
      sources: ["ISO 27001:2022 A.5.24", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.MA"] },

    { id: "p30-c13", title: "IRT-Betriebsanalyse und Leistungskennzahlen", titleEn: "IRT Operational Analytics & Performance Metrics",
      description: "Das Incident-Tracking-System muss regelmäßig für Trend-, Leistungs- und Kapazitätsanalysen ausgewertet werden. KPIs umfassen: Mean Time to Detect (MTTD), Mean Time to Respond (MTTR), Mean Time to Contain (MTTC), Eskalationsquote, Anteil wiederkehrender Vorfälle und IRT-Auslastung. Ergebnisse müssen vierteljährlich der Leitung berichtet und für die strategische Kapazitätsplanung verwendet werden. Die operative Erfassung und Registrierung eingehender Meldungen (Eingangsbestätigung, Vorgangskennung, SLA-Überwachung) wird in p31-c13 geregelt.",
      descriptionEn: "The incident tracking system must be regularly evaluated for trend, performance, and capacity analyses. KPIs include: Mean Time to Detect (MTTD), Mean Time to Respond (MTTR), Mean Time to Contain (MTTC), escalation rate, proportion of recurring incidents, and IRT utilisation. Results must be reported to management quarterly and used for strategic capacity planning. Operational capture and registration of incoming reports (acknowledgement, case ID, SLA monitoring) is governed in p31-c13.",
      reason: "Ohne Leistungsanalyse kann die Effektivität des IRT nicht bewertet und verbessert werden. Datengetriebene Metriken ermöglichen gezielte Investitionen in Personal und Werkzeuge.",
      reasonEn: "Without performance analysis, the effectiveness of the IRT cannot be assessed and improved. Data-driven metrics enable targeted investments in personnel and tools.",
      whenRequired: "Immer erforderlich für alle Sicherheitsvorfälle.",
      whenRequiredEn: "Always required for all security incidents.",
      sources: ["ISO 27001:2022 A.5.24", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.MA"] },

    { id: "p30-c14", title: "Strategische Wiederherstellungsentscheidungen", titleEn: "Strategic Recovery Decisions",
      description: "Wir müssen strategische Entscheidungsrahmen für die Wiederherstellung nach Sicherheitsvorfällen definieren. Dies umfasst: Freigabekriterien und -befugnisse für die Rückkehr in den Produktivbetrieb, Priorisierungsreihenfolge nach Geschäftskritikalität (unter Berücksichtigung der in p09 definierten kritischen Dienste), Entscheidung über Neuaufbau vs. Bereinigung bestehender Systeme und Kommunikation der Wiederherstellungszeitpläne an Stakeholder. Die operativen Bereinigung- und Wiederherstellungsschritte (Malware-Entfernung, Credential-Reset, Backup-Restauration) werden in p32-c03 geregelt.",
      descriptionEn: "We must define strategic decision frameworks for recovery after security incidents. This includes: release criteria and authorities for return to production, prioritisation order by business criticality (considering critical services defined in p09), decision on rebuild vs. cleanup of existing systems, and communication of recovery timelines to stakeholders. Operational eradication and recovery steps (malware removal, credential reset, backup restoration) are governed in p32-c03.",
      reason: "Strategische Wiederherstellungsentscheidungen — insbesondere die Freigabe für den Produktivbetrieb — erfordern klare Befugnisse und Kriterien, die unter Zeitdruck nicht improvisiert werden sollten.",
      reasonEn: "Strategic recovery decisions — especially release for production — require clear authorities and criteria that should not be improvised under time pressure.",
      whenRequired: "Erforderlich nach jedem Sicherheitsvorfall, der Systemwiederherstellung erfordert.",
      whenRequiredEn: "Required after every security incident requiring system recovery.",
      sources: ["ISO 27001:2022 A.5.26", "NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RC"] },

    { id: "p30-c15", title: "Versicherungsmanagement für Cybervorfälle", titleEn: "Cyber Incident Insurance Management",
      description: "Wir sollen prüfen, ob eine Cyberversicherung für den Schutz gegen finanzielle Folgen von Sicherheitsvorfällen sinnvoll ist. Die Versicherungspolice muss regelmäßig auf Abdeckungsumfang, Ausschlüsse, Meldepflichten und Kooperationsanforderungen überprüft werden. Die Meldeverfahren der Versicherung müssen in die Incident-Response-Prozesse integriert werden. Versicherungsanforderungen an die Sicherheitsmaßnahmen müssen eingehalten werden.",
      descriptionEn: "We should evaluate whether cyber insurance for protection against financial consequences of security incidents is appropriate. The insurance policy must be regularly reviewed for coverage scope, exclusions, notification requirements, and cooperation requirements. Insurance notification procedures must be integrated into incident response processes. Insurance requirements for security measures must be met.",
      reason: "Cybervorfälle können erhebliche finanzielle Folgen haben. Eine Cyberversicherung kann diese abmildern, erfordert aber die Einhaltung bestimmter Sicherheitsstandards und Meldepflichten.",
      reasonEn: "Cyber incidents can have significant financial consequences. Cyber insurance can mitigate these but requires compliance with certain security standards and notification obligations.",
      whenRequired: "Empfohlen für alle Organisationen, insbesondere solche mit hohem Datenvolumen oder regulatorischer Exposition.",
      whenRequiredEn: "Recommended for all organisations, especially those with high data volumes or regulatory exposure.",
      sources: ["ISO 27001:2022 A.5.24", "BSI IT-Grundschutz ISMS.1"] },

    { id: "p30-c16", title: "IRT-Fachausbildung und Kompetenzentwicklung", titleEn: "IRT Professional Training & Competence Development",
      description: "IRT-Mitglieder müssen spezifische technische und prozessuale Fachausbildungen erhalten. Der Schulungsplan muss abdecken: digitale Forensik, Malware-Analyse, Netzwerkforensik, Cloud-Incident-Response, Threat-Intelligence-Nutzung, Krisenmanagement und -kommunikation sowie rechtliche Aspekte der Beweissicherung. Zertifizierungen (z. B. GCIH, GCFA, ECIH) sollen gefördert werden. Mindestens jährlich müssen praktische Übungen (vgl. p30-c08) durchgeführt werden. Die allgemeine Schulung aller Mitarbeitenden zur Erkennung und Meldung von Vorfällen wird in p31-c21 geregelt.",
      descriptionEn: "IRT members must receive specific technical and procedural professional training. The training plan must cover: digital forensics, malware analysis, network forensics, cloud incident response, threat intelligence usage, crisis management and communication, and legal aspects of evidence preservation. Certifications (e.g., GCIH, GCFA, ECIH) should be encouraged. Practical exercises (cf. p30-c08) must be conducted at least annually. General training of all employees on incident recognition and reporting is governed in p31-c21.",
      reason: "IRT-Mitglieder benötigen spezialisierte Fachkenntnisse, die über allgemeine Security-Awareness hinausgehen. Ohne gezielte Fachausbildung fehlen im Ernstfall kritische Analysefähigkeiten.",
      reasonEn: "IRT members require specialised expertise beyond general security awareness. Without targeted professional training, critical analytical capabilities are lacking in emergencies.",
      whenRequired: "Immer erforderlich für alle IRT/CSIRT-Mitglieder.",
      whenRequiredEn: "Always required for all IRT/CSIRT members.",
      sources: ["ISO 27001:2022 A.6.3", "NIS2 Art.20(2)", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 PR.AT"] },

    { id: "p30-c17", title: "Überprüfung und Aktualisierung der Incident-Response-Richtlinie", titleEn: "Review & Update of Incident Response Policy",
      description: "Diese Richtlinie muss mindestens jährlich und nach jedem signifikanten Sicherheitsvorfall überprüft und aktualisiert werden. Lessons Learned aus Vorfällen und Übungen müssen in die Richtlinie einfließen. Änderungen an der Organisationsstruktur, IT-Infrastruktur oder regulatorischen Anforderungen erfordern eine außerplanmäßige Überprüfung. Alle Änderungen müssen genehmigt, kommuniziert und trainiert werden.",
      descriptionEn: "This policy must be reviewed and updated at least annually and after every significant security incident. Lessons learned from incidents and exercises must be incorporated. Changes to organisational structure, IT infrastructure, or regulatory requirements require unscheduled review. All changes must be approved, communicated, and trained.",
      reason: "Statische Incident-Response-Richtlinien werden zunehmend unwirksam. Nur durch kontinuierliche Verbesserung auf Basis realer Erfahrungen bleibt die Richtlinie relevant und effektiv.",
      reasonEn: "Static incident response policies become increasingly ineffective. Only through continuous improvement based on real experiences does the policy remain relevant and effective.",
      whenRequired: "Immer erforderlich als Teil des ISMS-Regelkreises.",
      whenRequiredEn: "Always required as part of the ISMS cycle.",
      sources: ["ISO 27001:2022 §10.1-10.2", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.IM"] },
  ],

  // ═══════════════════════════════════════════════════════════════
  // P31 — Incident Reporting Policy
  // ═══════════════════════════════════════════════════════════════
  p31: [
    { id: "p31-c00", title: "Meldepflicht und Meldekultur", titleEn: "Reporting Obligation & Reporting Culture",
      description: "Jeder Mitarbeitende, Auftragnehmer oder Dritte ist verpflichtet, erkannte oder vermutete Sicherheitsvorfälle, Schwachstellen und Richtlinienverstöße unverzüglich zu melden. Wir müssen eine Kultur fördern, in der Meldungen erwünscht sind und Meldende keine negativen Konsequenzen befürchten müssen (No-Blame-Kultur). Anonyme Meldemöglichkeiten müssen bereitgestellt werden.",
      descriptionEn: "Every employee, contractor, or third party is obligated to immediately report recognised or suspected security incidents, vulnerabilities, and policy violations. We must foster a culture where reports are welcomed and reporters need not fear negative consequences (no-blame culture). Anonymous reporting options must be provided.",
      reason: "Viele Vorfälle werden aus Angst vor Schuldzuweisungen nicht gemeldet. Eine No-Blame-Kultur erhöht die Meldequote und ermöglicht frühzeitige Erkennung.",
      reasonEn: "Many incidents are not reported due to fear of blame. A no-blame culture increases the reporting rate and enables early detection.",
      whenRequired: "Immer erforderlich als Grundlage des Meldesystems.",
      whenRequiredEn: "Always required as the foundation of the reporting system.",
      sources: ["ISO 27001:2022 A.6.8", "NIS2 Art.23", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.CO"] },

    { id: "p31-c01", title: "Interne Meldekanäle und -verfahren", titleEn: "Internal Reporting Channels & Procedures",
      description: "Wir müssen klare, leicht zugängliche Meldekanäle für Sicherheitsvorfälle bereitstellen. Mindestens folgende Kanäle müssen verfügbar sein: dedizierte E-Mail-Adresse (z.B. security@organisation.tld), Telefon-Hotline (24/7 für kritische Vorfälle), Ticketsystem/Webformular und persönliche Meldung an den Vorgesetzten. Die Kanäle müssen allen Mitarbeitenden bekannt sein und regelmäßig kommuniziert werden.",
      descriptionEn: "We must provide clear, easily accessible reporting channels for security incidents. At minimum, the following channels must be available: dedicated email address (e.g., security@organisation.tld), telephone hotline (24/7 for critical incidents), ticket system/web form, and personal report to supervisor. Channels must be known to all employees and regularly communicated.",
      reason: "Komplizierte oder unbekannte Meldewege führen zu verspäteten oder unterlassenen Meldungen. Einfache, vielfältige Kanäle senken die Hemmschwelle zur Meldung.",
      reasonEn: "Complicated or unknown reporting channels lead to delayed or omitted reports. Simple, diverse channels lower the barrier to reporting.",
      whenRequired: "Immer erforderlich für alle Organisationen.",
      whenRequiredEn: "Always required for all organisations.",
      sources: ["ISO 27001:2022 A.6.8", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.CO"] },

    { id: "p31-c02", title: "Regulatorische und interne Meldefristen", titleEn: "Regulatory & Internal Reporting Deadlines",
      description: "Wir müssen ein integriertes Fristensystem für alle Meldepflichten einhalten. Regulatorische Fristen: NIS2-Frühwarnung innerhalb von 24 Stunden, NIS2-Vorfallbenachrichtigung innerhalb von 72 Stunden, NIS2-Abschlussbericht innerhalb eines Monats (Art. 23). DSGVO-Meldung an die Aufsichtsbehörde innerhalb von 72 Stunden (Art. 33). Interne Fristen: Sofortmeldung (innerhalb von 30 Minuten) für kritische Vorfälle (aktiver Ransomware-Angriff, bestätigte Datenpanne), zeitnahe Meldung (innerhalb von 4 Stunden) für hohe Vorfälle, Meldung am selben Arbeitstag für mittlere Vorfälle. Meldepflichtige Schwellenwerte müssen klar definiert und allen Beteiligten bekannt sein.",
      descriptionEn: "We must maintain an integrated deadline system for all reporting obligations. Regulatory deadlines: NIS2 early warning within 24 hours, NIS2 incident notification within 72 hours, NIS2 final report within one month (Art. 23). GDPR notification to supervisory authority within 72 hours (Art. 33). Internal deadlines: immediate report (within 30 minutes) for critical incidents (active ransomware attack, confirmed data breach), prompt report (within 4 hours) for high incidents, same-business-day report for medium incidents. Reportable thresholds must be clearly defined and known to all stakeholders.",
      reason: "Die Vielzahl paralleler Meldefristen (NIS2, DSGVO, intern) erfordert ein integriertes Fristensystem, um keine Frist zu versäumen und Bußgelder zu vermeiden.",
      reasonEn: "The multitude of parallel reporting deadlines (NIS2, GDPR, internal) requires an integrated deadline system to avoid missing any deadline and prevent fines.",
      whenRequired: "Verpflichtend für alle NIS2-regulierten Organisationen.",
      whenRequiredEn: "Mandatory for all NIS2-regulated organisations.",
      sources: ["NIS2 Art.23(1)-(4)", "DSGVO Art.33(1)", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p31-c03", title: "DSGVO-Meldepflichten bei Datenschutzverletzungen", titleEn: "GDPR Notification for Data Breaches",
      description: "Bei Verletzungen des Schutzes personenbezogener Daten muss die Organisation die DSGVO-Meldepflichten einhalten: Meldung an die Datenschutzaufsichtsbehörde innerhalb von 72 Stunden, sofern ein Risiko für die Rechte und Freiheiten der betroffenen Personen besteht. Bei hohem Risiko müssen auch die betroffenen Personen unverzüglich benachrichtigt werden. Der Datenschutzbeauftragte muss in den Meldeprozess eingebunden sein.",
      descriptionEn: "In case of personal data breaches, we must comply with GDPR notification obligations: notification to the data protection supervisory authority within 72 hours if there is a risk to the rights and freedoms of affected individuals. In case of high risk, affected individuals must also be notified without undue delay. The Data Protection Officer must be involved in the notification process.",
      reason: "DSGVO-Meldepflichten laufen parallel zu NIS2-Meldepflichten. Ohne integrierte Prozesse besteht die Gefahr, eine der Fristen zu versäumen.",
      reasonEn: "GDPR notification obligations run parallel to NIS2 obligations. Without integrated processes, there is a risk of missing one of the deadlines.",
      whenRequired: "Erforderlich bei jeder Verletzung des Schutzes personenbezogener Daten.",
      whenRequiredEn: "Required for every personal data breach.",
      sources: ["DSGVO Art.33-34", "ISO 27001:2022 A.5.24", "BSI IT-Grundschutz CON.2"] },

    { id: "p31-c04", title: "Mindestinhalte und Meldeformulare", titleEn: "Minimum Report Contents & Reporting Forms",
      description: "Jede Vorfallmeldung muss mindestens folgende Informationen enthalten: Zeitpunkt der Entdeckung, Art des Vorfalls, betroffene Systeme und Daten, geschätzte Auswirkung, erste Eindämmungsmaßnahmen, Kontaktdaten des Meldenden, Schweregrad-Einschätzung und bereits benachrichtigte Stellen. Standardisierte Meldeformulare müssen für verschiedene Szenarien bereitgestellt werden: interne Erstmeldung, NIS2-Frühwarnung (24h), NIS2-Vorfallbenachrichtigung (72h), NIS2-Abschlussbericht, DSGVO-Meldung an Aufsichtsbehörde und Benachrichtigung betroffener Personen. Formulare müssen vorausgefüllt und digital zugänglich sein, um unter Zeitdruck keine Pflichtfelder zu vergessen.",
      descriptionEn: "Every incident report must contain at minimum: time of discovery, type of incident, affected systems and data, estimated impact, initial containment measures, reporter contact details, severity assessment, and parties already notified. Standardised reporting forms must be provided for various scenarios: internal initial report, NIS2 early warning (24h), NIS2 incident notification (72h), NIS2 final report, GDPR notification to supervisory authority, and notification of affected individuals. Forms must be pre-filled and digitally accessible to avoid missing mandatory fields under time pressure.",
      reason: "Unvollständige Meldungen verzögern die Bewertung und Reaktion. Standardisierte Formulare mit vordefinierten Pflichtfeldern beschleunigen die Meldung und stellen Vollständigkeit sicher.",
      reasonEn: "Incomplete reports delay assessment and response. Standardised forms with pre-defined mandatory fields accelerate reporting and ensure completeness.",
      whenRequired: "Erforderlich für jede Vorfallmeldung.",
      whenRequiredEn: "Required for every incident report.",
      sources: ["ISO 27001:2022 A.6.8", "NIS2 Art.23(3)-(4)", "DSGVO Art.33(3)", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p31-c05", title: "Vertraulichkeit von Vorfallmeldungen", titleEn: "Confidentiality of Incident Reports",
      description: "Vorfallmeldungen und zugehörige Informationen müssen als vertraulich behandelt werden. Der Zugang muss auf das für die Bearbeitung notwendige Personal beschränkt sein. Informationen über Vorfälle dürfen nur an autorisierte Stellen weitergegeben werden. Die Identität von Meldenden muss geschützt werden, sofern keine rechtliche Pflicht zur Offenlegung besteht.",
      descriptionEn: "Incident reports and associated information must be treated as confidential. Access must be restricted to personnel necessary for handling. Information about incidents may only be shared with authorised parties. The identity of reporters must be protected unless there is a legal obligation to disclose.",
      reason: "Unkontrollierte Weitergabe von Vorfalldetails kann den Schaden vergrößern, Ermittlungen behindern und die Bereitschaft zur Meldung senken.",
      reasonEn: "Uncontrolled sharing of incident details can amplify damage, hinder investigations, and reduce willingness to report.",
      whenRequired: "Immer erforderlich für alle Vorfallmeldungen.",
      whenRequiredEn: "Always required for all incident reports.",
      sources: ["ISO 27001:2022 A.5.25", "DSGVO Art.5(1)(f)", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p31-c06", title: "Melde-Eskalationsmatrix", titleEn: "Reporting Escalation Matrix",
      description: "Eine Eskalationsmatrix muss definieren, welche Vorfälle an welche Ebene gemeldet werden: P4-Niedrig an IT-Sicherheitsteam, P3-Mittel an CISO, P2-Hoch an Geschäftsleitung und CISO, P1-Kritisch an Vorstand, Krisenstab und externe Behörden. Kontaktdaten und Erreichbarkeiten müssen aktuell gehalten werden. Die Matrix muss in allen Playbooks und an Meldepunkten verfügbar sein.",
      descriptionEn: "An escalation matrix must define which incidents are reported to which level: P4-Low to IT security team, P3-Medium to CISO, P2-High to executive management and CISO, P1-Critical to board, crisis team, and external authorities. Contact details and availability must be kept current. The matrix must be available in all playbooks and at reporting points.",
      reason: "Ohne klare Eskalationsmatrix werden kritische Vorfälle an die falsche Ebene gemeldet oder die Eskalation verzögert sich.",
      reasonEn: "Without a clear escalation matrix, critical incidents are reported to the wrong level or escalation is delayed.",
      whenRequired: "Immer erforderlich als Teil des Meldesystems.",
      whenRequiredEn: "Always required as part of the reporting system.",
      sources: ["ISO 27001:2022 A.5.25", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.CO"] },

    { id: "p31-c07", title: "Alert-to-Report-Kanalintegration", titleEn: "Alert-to-Report Channel Integration",
      description: "Automatisierte Alerts aus technischen Sicherheitssystemen müssen nahtlos in das Incident-Tracking-System integriert werden. Für jeden automatisch generierten Alert muss definiert sein, ob er direkt einen Vorfallbericht erzeugt oder zunächst zur manuellen Bewertung weitergeleitet wird. Schwellenwerte für automatische Ticket-Erstellung und Eskalation müssen konfiguriert sein. Die technische Alert-Logik (Korrelationsregeln, SIEM-Tuning, False-Positive-Reduktion) wird in p26 und p28 geregelt; diese Klausel fokussiert auf die Schnittstellendefinition zwischen Alerting und dem Meldeworkflow.",
      descriptionEn: "Automated alerts from technical security systems must be seamlessly integrated into the incident tracking system. For each automatically generated alert, it must be defined whether it directly creates an incident report or is first routed for manual assessment. Thresholds for automatic ticket creation and escalation must be configured. Technical alert logic (correlation rules, SIEM tuning, false-positive reduction) is governed in p26 and p28; this clause focuses on the interface definition between alerting and the reporting workflow.",
      reason: "Ohne klare Schnittstellendefinition entstehen entweder manuelle Lücken (Alerts werden nicht zu Tickets) oder Überflutung (jeder Alert erzeugt ein Ticket). Die Kanalintegration ist der Schlüssel zur effizienten Meldekette.",
      reasonEn: "Without clear interface definition, either manual gaps arise (alerts don't become tickets) or flooding occurs (every alert creates a ticket). Channel integration is key to an efficient reporting chain.",
      whenRequired: "Erforderlich für alle Organisationen mit technischen Sicherheitssystemen.",
      whenRequiredEn: "Required for all organisations with technical security systems.",
      sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz DER.1.1", "NIST CSF 2.0 DE.AE"] },

    { id: "p31-c08", title: "Meldung an sektorale CERTs und ISACs", titleEn: "Reporting to Sectoral CERTs & ISACs",
      description: "Wir müssen Verfahren für die Meldung an sektorale CERTs (Computer Emergency Response Teams) und ISACs (Information Sharing and Analysis Centres) definieren. Kontaktdaten und Meldeformate der zuständigen CERTs müssen dokumentiert sein. Der Informationsaustausch über Bedrohungen und Indikatoren (IoC-Sharing) mit vertrauenswürdigen Partnern soll unter Verwendung standardisierter Formate (STIX/TAXII) erfolgen.",
      descriptionEn: "We must define procedures for reporting to sectoral CERTs (Computer Emergency Response Teams) and ISACs (Information Sharing and Analysis Centres). Contact details and reporting formats of responsible CERTs must be documented. Threat and indicator sharing (IoC sharing) with trusted partners should use standardised formats (STIX/TAXII).",
      reason: "Sektorale CERTs und ISACs bieten wertvolle Unterstützung und ermöglichen den Austausch von Bedrohungsinformationen, die anderen Organisationen helfen können.",
      reasonEn: "Sectoral CERTs and ISACs provide valuable support and enable sharing of threat information that can help other organisations.",
      whenRequired: "Erforderlich für NIS2-regulierte Organisationen, empfohlen für alle.",
      whenRequiredEn: "Required for NIS2-regulated organisations, recommended for all.",
      sources: ["NIS2 Art.23(1)", "NIS2 Art.29", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p31-c09", title: "Meldung an Kunden und Geschäftspartner", titleEn: "Notification to Customers & Business Partners",
      description: "Wenn ein Vorfall Kunden oder Geschäftspartner betreffen könnte, müssen diese zeitnah und angemessen informiert werden. Kriterien für die Benachrichtigung müssen vorab definiert sein. Kommunikationsvorlagen müssen vorbereitet sein, die sachlich und transparent über Art, Umfang und empfohlene Schutzmaßnahmen informieren. Vertragliche Meldepflichten gegenüber Kunden und Partnern müssen eingehalten werden.",
      descriptionEn: "When an incident could affect customers or business partners, they must be informed promptly and appropriately. Criteria for notification must be pre-defined. Communication templates must be prepared that inform factually and transparently about type, scope, and recommended protective measures. Contractual notification obligations to customers and partners must be met.",
      reason: "Verspätete oder unzureichende Kundenbenachrichtigung kann das Vertrauen nachhaltig beschädigen und vertragliche Pflichten verletzen.",
      reasonEn: "Delayed or insufficient customer notification can permanently damage trust and violate contractual obligations.",
      whenRequired: "Erforderlich bei Vorfällen, die Kunden oder Partner betreffen.",
      whenRequiredEn: "Required for incidents affecting customers or partners.",
      sources: ["NIS2 Art.23(1)", "DSGVO Art.34", "ISO 27001:2022 A.5.25"] },

    { id: "p31-c10", title: "Berichterstattung an die Geschäftsleitung", titleEn: "Reporting to Executive Management",
      description: "Die Geschäftsleitung muss regelmäßig (mindestens vierteljährlich) über die Vorfallsituation informiert werden. Berichte müssen umfassen: Anzahl und Art der Vorfälle, Trends, Kosten und Auswirkungen, Wirksamkeit der Reaktion und strategische Empfehlungen. Bei kritischen Vorfällen muss eine sofortige Ad-hoc-Berichterstattung erfolgen. Berichte müssen in Management-gerechter Sprache verfasst sein.",
      descriptionEn: "Executive management must be regularly informed (at least quarterly) about the incident situation. Reports must include: number and type of incidents, trends, costs and impacts, response effectiveness, and strategic recommendations. For critical incidents, immediate ad-hoc reporting must occur. Reports must be written in management-appropriate language.",
      reason: "NIS2 fordert die Verantwortung der Geschäftsleitung für Cybersicherheit. Regelmäßige Berichterstattung stellt informierte Entscheidungsfindung sicher.",
      reasonEn: "NIS2 requires executive management responsibility for cybersecurity. Regular reporting ensures informed decision-making.",
      whenRequired: "Immer erforderlich als NIS2-Anforderung.",
      whenRequiredEn: "Always required as a NIS2 requirement.",
      sources: ["NIS2 Art.20(1)", "ISO 27001:2022 §9.3", "BSI IT-Grundschutz ISMS.1"] },

    { id: "p31-c11", title: "Melderegistrierung und Nachverfolgung", titleEn: "Report Registration & Follow-Up",
      description: "Jede eingegangene Meldung muss im Tracking-System registriert werden und eine eindeutige Vorgangskennung erhalten. Dem Meldenden muss innerhalb von 2 Stunden eine Eingangsbestätigung mit der Vorgangskennung zugesandt werden. Status-Updates müssen in festgelegten Intervallen an relevante Stakeholder kommuniziert werden. Offene Meldungen müssen eskaliert werden, wenn sie innerhalb der definierten SLAs nicht bearbeitet werden.",
      descriptionEn: "Every received report must be registered in the tracking system and receive a unique case identifier. The reporter must receive an acknowledgement with the case identifier within 2 hours. Status updates must be communicated to relevant stakeholders at defined intervals. Open reports must be escalated if not processed within defined SLAs.",
      reason: "Ohne systematische Registrierung und Nachverfolgung gehen Meldungen verloren oder werden nicht zeitnah bearbeitet.",
      reasonEn: "Without systematic registration and follow-up, reports are lost or not processed promptly.",
      whenRequired: "Erforderlich für alle eingegangenen Vorfallmeldungen.",
      whenRequiredEn: "Required for all received incident reports.",
      sources: ["ISO 27001:2022 A.5.24", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.MA"] },

    { id: "p31-c12", title: "Eingehende Drittanbieter-Meldungen verarbeiten", titleEn: "Processing Incoming Third-Party Reports",
      description: "Wir müssen Verfahren definieren, wie eingehende Sicherheitsmeldungen von Drittanbietern und Dienstleistern empfangen, bewertet und in das eigene Incident Management integriert werden. Eingehende Meldungen müssen den gleichen Triage- und Tracking-Prozessen unterzogen werden wie interne Meldungen. Kontaktpunkte und Kommunikationskanäle für den Empfang externer Meldungen müssen definiert sein. Die vertraglichen Anforderungen an Drittanbieter bezüglich Meldepflichten, Fristen und Informationstiefe werden in p42/p43 (Lieferantensicherheit) geregelt.",
      descriptionEn: "We must define procedures for receiving, assessing, and integrating incoming security reports from third-party vendors and service providers into its own incident management. Incoming reports must undergo the same triage and tracking processes as internal reports. Contact points and communication channels for receiving external reports must be defined. Contractual requirements for third parties regarding reporting obligations, deadlines, and information depth are governed in p42/p43 (Supplier Security).",
      reason: "Eingehende Drittanbieter-Meldungen erfordern einen definierten Empfangs- und Integrationsprozess, um Verzögerungen bei der Reaktion auf Lieferketten-Vorfälle zu vermeiden.",
      reasonEn: "Incoming third-party reports require a defined reception and integration process to avoid delays in responding to supply chain incidents.",
      whenRequired: "Erforderlich für alle Organisationen mit IT-Drittanbietern.",
      whenRequiredEn: "Required for all organisations with IT third-party vendors.",
      sources: ["NIS2 Art.21(2)(d)", "ISO 27001:2022 A.5.19-A.5.22", "BSI IT-Grundschutz OPS.2.1"] },

    { id: "p31-c13", title: "Meldequalität und kontinuierliche Verbesserung", titleEn: "Reporting Quality & Continuous Improvement",
      description: "Die Qualität der Vorfallmeldungen muss regelmäßig bewertet werden. Metriken umfassen: Vollständigkeit der Meldungen, Einhaltung der Meldefristen, False-Positive-Rate, Meldequote (gemeldete vs. erkannte Vorfälle) und Zufriedenheit der Meldenden mit dem Prozess. Basierend auf der Auswertung müssen Verbesserungsmaßnahmen für Formulare, Kanäle und Schulungen abgeleitet werden.",
      descriptionEn: "The quality of incident reports must be regularly evaluated. Metrics include: completeness of reports, compliance with reporting deadlines, false-positive rate, reporting rate (reported vs. detected incidents), and reporter satisfaction with the process. Based on evaluation, improvement measures for forms, channels, and training must be derived.",
      reason: "Ein Meldesystem, das nicht kontinuierlich verbessert wird, verliert an Akzeptanz und Effektivität. Qualitätsmetriken identifizieren Schwachstellen im Meldeprozess.",
      reasonEn: "A reporting system that is not continuously improved loses acceptance and effectiveness. Quality metrics identify weaknesses in the reporting process.",
      whenRequired: "Erforderlich als Teil des kontinuierlichen Verbesserungsprozesses.",
      whenRequiredEn: "Required as part of the continuous improvement process.",
      sources: ["ISO 27001:2022 §10.1", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.IM"] },

    { id: "p31-c14", title: "Whistleblower-Integration", titleEn: "Whistleblower Integration",
      description: "Das Meldesystem für Sicherheitsvorfälle muss mit dem Hinweisgebersystem der Organisation (gemäß HinSchG/EU-Whistleblower-Richtlinie) koordiniert werden. Sicherheitsrelevante Hinweise über den Whistleblower-Kanal müssen an das IRT weitergeleitet werden. Die besonderen Schutzrechte des Hinweisgebers müssen gewahrt bleiben. Doppelmeldungen über verschiedene Kanäle müssen erkannt und konsolidiert werden.",
      descriptionEn: "The security incident reporting system must be coordinated with the organisation's whistleblower system (per HinSchG/EU Whistleblower Directive). Security-relevant tips through the whistleblower channel must be forwarded to the IRT. The special protection rights of the whistleblower must be maintained. Duplicate reports through different channels must be detected and consolidated.",
      reason: "Sicherheitsvorfälle können auch über Whistleblower-Kanäle gemeldet werden. Ohne Integration gehen diese Meldungen möglicherweise verloren oder werden verspätet bearbeitet.",
      reasonEn: "Security incidents may also be reported through whistleblower channels. Without integration, these reports may be lost or processed late.",
      whenRequired: "Erforderlich für Organisationen mit Hinweisgebersystem.",
      whenRequiredEn: "Required for organisations with a whistleblower system.",
      sources: ["EU-Whistleblower-Richtlinie 2019/1937", "HinSchG", "ISO 27001:2022 A.6.8"] },

    { id: "p31-c15", title: "Near-Miss-Meldungen", titleEn: "Near-Miss Reporting",
      description: "Neben tatsächlichen Vorfällen müssen auch Near-Misses (Beinahe-Vorfälle) gemeldet und dokumentiert werden. Near-Misses umfassen: abgewehrte Angriffe, erkannte aber nicht ausgenutzte Schwachstellen, erfolgloses Phishing und rechtzeitig korrigierte Fehlkonfigurationen. Die Analyse von Near-Misses bietet wertvolle Erkenntnisse für die Prävention und muss in regelmäßige Sicherheitsberichte einfließen.",
      descriptionEn: "In addition to actual incidents, near-misses must also be reported and documented. Near-misses include: repelled attacks, identified but unexploited vulnerabilities, unsuccessful phishing, and timely corrected misconfigurations. Analysis of near-misses provides valuable insights for prevention and must feed into regular security reports.",
      reason: "Near-Misses sind Frühwarnsignale für potenzielle Vorfälle. Ihre systematische Erfassung ermöglicht proaktive Verbesserungen, bevor ein tatsächlicher Schaden eintritt.",
      reasonEn: "Near-misses are early warning signals for potential incidents. Their systematic capture enables proactive improvements before actual damage occurs.",
      whenRequired: "Empfohlen für alle Organisationen, insbesondere mit Sicherheitsmonitoring.",
      whenRequiredEn: "Recommended for all organisations, especially those with security monitoring.",
      sources: ["ISO 27001:2022 A.5.24", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 DE.AE"] },

    { id: "p31-c16", title: "Meldepflichten bei Cloud- und SaaS-Vorfällen", titleEn: "Reporting Obligations for Cloud & SaaS Incidents",
      description: "Spezifische Meldeverfahren müssen für Vorfälle definiert werden, die Cloud-Dienste oder SaaS-Anwendungen betreffen. Cloud-Provider-Benachrichtigungen über Sicherheitsereignisse müssen systematisch empfangen und bewertet werden. Wir müssen verstehen, welche Meldepflichten beim Provider und welche bei der Organisation selbst liegen (Shared Responsibility). Verfahren für die koordinierte Vorfallbehandlung mit Cloud-Providern müssen definiert sein.",
      descriptionEn: "Specific reporting procedures must be defined for incidents affecting cloud services or SaaS applications. Cloud provider notifications about security events must be systematically received and assessed. We must understand which reporting obligations lie with the provider and which with the organisation itself (shared responsibility). Procedures for coordinated incident handling with cloud providers must be defined.",
      reason: "Cloud-Umgebungen erfordern spezifische Meldeverfahren aufgrund der geteilten Verantwortung. Ohne klare Verfahren besteht die Gefahr, dass Vorfälle weder vom Provider noch von der Organisation gemeldet werden.",
      reasonEn: "Cloud environments require specific reporting procedures due to shared responsibility. Without clear procedures, incidents risk being reported by neither the provider nor the organisation.",
      whenRequired: "Erforderlich für alle Organisationen mit Cloud- oder SaaS-Nutzung.",
      whenRequiredEn: "Required for all organisations using cloud or SaaS services.",
      sources: ["ISO 27001:2022 A.5.23", "NIS2 Art.21(2)(d)", "BSI C5:2020", "NIST CSF 2.0 RS.CO"] },

    { id: "p31-c17", title: "Sprachregelungen und Kommunikationsrichtlinien", titleEn: "Communication Guidelines & Talking Points",
      description: "Für die Kommunikation über Sicherheitsvorfälle müssen Sprachregelungen definiert werden. Technische Details dürfen nur an autorisiertes Personal kommuniziert werden. Für die externe Kommunikation müssen vorbereitete Sprachbausteine und Q&A-Dokumente bereitstehen. Mitarbeitende müssen angewiesen werden, keine eigenmächtigen Aussagen gegenüber Medien, Kunden oder Dritten zu machen. Social-Media-Richtlinien für Vorfälle müssen definiert sein.",
      descriptionEn: "Communication guidelines must be defined for communication about security incidents. Technical details may only be communicated to authorised personnel. For external communication, prepared talking points and Q&A documents must be available. Employees must be instructed not to make independent statements to media, customers, or third parties. Social media guidelines for incidents must be defined.",
      reason: "Unkontrollierte Kommunikation über Vorfälle kann den Schaden vervielfachen. Einheitliche Sprachregelungen schützen die Organisation vor Reputationsschäden und rechtlichen Risiken.",
      reasonEn: "Uncontrolled communication about incidents can multiply damage. Uniform communication guidelines protect the organisation from reputational damage and legal risks.",
      whenRequired: "Erforderlich für alle Vorfälle mit potenziellem externen Interesse.",
      whenRequiredEn: "Required for all incidents with potential external interest.",
      sources: ["ISO 27001:2022 A.5.25", "NIS2 Art.23", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p31-c18", title: "Dokumentationspflichten und Aufbewahrungsfristen", titleEn: "Documentation Obligations & Retention Periods",
      description: "Alle Vorfallmeldungen, Bewertungen, Maßnahmen und Berichte müssen dokumentiert und gemäß definierten Aufbewahrungsfristen archiviert werden. Mindestaufbewahrungsfristen: regulatorische Meldungen 10 Jahre, interne Vorfallberichte 5 Jahre, forensische Beweise bis zum Abschluss aller rechtlichen Verfahren. Die Dokumentation muss revisionssicher und jederzeit für Audits zugänglich sein.",
      descriptionEn: "All incident reports, assessments, measures, and reports must be documented and archived according to defined retention periods. Minimum retention periods: regulatory reports 10 years, internal incident reports 5 years, forensic evidence until conclusion of all legal proceedings. Documentation must be audit-proof and accessible for audits at all times.",
      reason: "Regulatorische und rechtliche Anforderungen verlangen die Aufbewahrung von Vorfallsdokumentationen über definierte Zeiträume. Fehlende Dokumentation kann bei Audits zu Beanstandungen führen.",
      reasonEn: "Regulatory and legal requirements demand retention of incident documentation for defined periods. Missing documentation can lead to findings during audits.",
      whenRequired: "Immer erforderlich für alle dokumentierten Vorfälle.",
      whenRequiredEn: "Always required for all documented incidents.",
      sources: ["NIS2 Art.23(4)", "DSGVO Art.5(2)", "ISO 27001:2022 A.5.33", "BSI IT-Grundschutz OPS.1.2.2"] },

    { id: "p31-c19", title: "Schulung zur Vorfallmeldung", titleEn: "Incident Reporting Training",
      description: "Alle Mitarbeitenden müssen regelmäßig (mindestens jährlich) zur Vorfallmeldung geschult werden. Schulungsinhalte umfassen: Erkennung von Sicherheitsvorfällen, Nutzung der Meldekanäle, Ausfüllen von Meldeformularen, Verständnis der Meldefristen und Sensibilisierung für die No-Blame-Kultur. Neue Mitarbeitende müssen im Onboarding geschult werden. Die Schulungsteilnahme muss dokumentiert und nachverfolgt werden.",
      descriptionEn: "All employees must be regularly trained (at least annually) on incident reporting. Training content includes: recognition of security incidents, use of reporting channels, completing reporting forms, understanding reporting deadlines, and awareness of no-blame culture. New employees must be trained during onboarding. Training participation must be documented and tracked.",
      reason: "Schulung ist die Grundvoraussetzung dafür, dass Vorfälle überhaupt gemeldet werden. Ohne regelmäßige Schulung sinkt die Meldequote und die Qualität der Meldungen.",
      reasonEn: "Training is the prerequisite for incidents being reported at all. Without regular training, the reporting rate and quality of reports decrease.",
      whenRequired: "Immer erforderlich für alle Mitarbeitenden.",
      whenRequiredEn: "Always required for all employees.",
      sources: ["NIS2 Art.20(2)", "ISO 27001:2022 A.6.3", "BSI IT-Grundschutz ORP.3"] },

    { id: "p31-c20", title: "Überprüfung und Aktualisierung der Melderichtlinie", titleEn: "Review & Update of Reporting Policy",
      description: "Diese Richtlinie muss mindestens jährlich sowie nach signifikanten Vorfällen oder regulatorischen Änderungen überprüft und aktualisiert werden. Die Wirksamkeit des Meldesystems muss anhand definierter KPIs bewertet werden. Änderungen müssen genehmigt, dokumentiert und an alle Beteiligten kommuniziert werden. Feedback von Meldenden und IRT-Mitgliedern muss in die Überarbeitung einfließen.",
      descriptionEn: "This policy must be reviewed and updated at least annually and after significant incidents or regulatory changes. The effectiveness of the reporting system must be evaluated using defined KPIs. Changes must be approved, documented, and communicated to all stakeholders. Feedback from reporters and IRT members must feed into the revision.",
      reason: "Statische Melderichtlinien verlieren an Relevanz. Regelmäßige Überprüfung stellt sicher, dass die Richtlinie aktuelle Bedrohungen und Anforderungen berücksichtigt.",
      reasonEn: "Static reporting policies lose relevance. Regular review ensures the policy considers current threats and requirements.",
      whenRequired: "Immer erforderlich als Teil des ISMS-Regelkreises.",
      whenRequiredEn: "Always required as part of the ISMS cycle.",
      sources: ["ISO 27001:2022 §10.1-10.2", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.IM"] },
  ],

  // ═══════════════════════════════════════════════════════════════
  // P32 — Incident Handling Procedures
  // ═══════════════════════════════════════════════════════════════
  p32: [
    { id: "p32-c00", title: "Vorfallaufnahme und initiale Triage", titleEn: "Incident Intake & Initial Triage",
      description: "Eingehende Vorfallmeldungen müssen nach einem standardisierten Verfahren aufgenommen und einer initialen Triage unterzogen werden. Die Triage muss innerhalb von 15 Minuten nach Eingang erfolgen und umfasst: Bestätigung als Sicherheitsvorfall (vs. Fehlalarm oder IT-Störung), vorläufige Schweregrad-Einstufung, Zuordnung zum zuständigen Analysten und Erfassung im Tracking-System. Automatisierte Triage-Unterstützung soll implementiert werden.",
      descriptionEn: "Incoming incident reports must be received and subjected to initial triage following a standardised procedure. Triage must occur within 15 minutes of receipt and includes: confirmation as security incident (vs. false alarm or IT disruption), preliminary severity classification, assignment to responsible analyst, and capture in tracking system. Automated triage support should be implemented.",
      reason: "Schnelle und korrekte Triage ist entscheidend für die Priorisierung der Reaktion. Fehlklassifizierungen führen entweder zu unverhältnismäßigem Aufwand oder zu unzureichender Reaktion.",
      reasonEn: "Fast and correct triage is crucial for prioritising response. Misclassifications lead either to disproportionate effort or insufficient response.",
      whenRequired: "Erforderlich für jeden eingehenden Sicherheitsvorfall.",
      whenRequiredEn: "Required for every incoming security incident.",
      sources: ["ISO 27001:2022 A.5.25", "NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p32-c01", title: "Detailanalyse und Schadensumfang-Bestimmung", titleEn: "Detailed Analysis & Impact Assessment",
      description: "Nach der initialen Triage muss eine detaillierte Analyse des Vorfalls durchgeführt werden. Diese umfasst: Identifizierung des Angriffsvektors und der Angriffstechniken (MITRE ATT&CK Mapping), Bestimmung aller betroffenen Systeme und Daten, Abschätzung des Geschäftsimpacts, Identifizierung des Zeitpunkts der initialen Kompromittierung und Bewertung der aktuellen Bedrohungslage (ist der Angreifer noch aktiv?).",
      descriptionEn: "After initial triage, a detailed analysis of the incident must be conducted. This includes: identification of the attack vector and techniques (MITRE ATT&CK mapping), determination of all affected systems and data, estimation of business impact, identification of the initial compromise time, and assessment of the current threat situation (is the attacker still active?).",
      reason: "Ohne vollständiges Verständnis des Vorfalls können Eindämmungs- und Bereinigungsmaßnahmen unvollständig sein und zu erneuter Kompromittierung führen.",
      reasonEn: "Without complete understanding of the incident, containment and remediation measures may be incomplete and lead to re-compromise.",
      whenRequired: "Erforderlich für alle bestätigten Sicherheitsvorfälle.",
      whenRequiredEn: "Required for all confirmed security incidents.",
      sources: ["NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1", "MITRE ATT&CK", "NIST CSF 2.0 RS.AN"] },

    { id: "p32-c02", title: "Eindämmung — Kurzfristige Sofortmaßnahmen", titleEn: "Containment — Short-Term Immediate Actions",
      description: "Sofortige Eindämmungsmaßnahmen müssen die weitere Ausbreitung des Vorfalls verhindern, ohne forensische Beweise zu zerstören. Maßnahmen umfassen je nach Szenario: Netzwerkisolierung betroffener Systeme, Sperrung kompromittierter Konten, Blockierung bekannter IoC (IP-Adressen, Domains, Hashes), Deaktivierung betroffener Dienste und Aktivierung zusätzlicher Überwachung. Jede Maßnahme muss dokumentiert und mit Zeitstempel versehen werden.",
      descriptionEn: "Immediate containment measures must prevent further spread of the incident without destroying forensic evidence. Measures include depending on scenario: network isolation of affected systems, locking compromised accounts, blocking known IoC (IP addresses, domains, hashes), disabling affected services, and activating additional monitoring. Every measure must be documented with timestamp.",
      reason: "Jede Minute Verzögerung bei der Eindämmung ermöglicht dem Angreifer weitere Ausbreitung und größeren Schaden. Sofortige, vordefinierte Maßnahmen minimieren die Auswirkung.",
      reasonEn: "Every minute of delay in containment allows the attacker further spread and greater damage. Immediate, pre-defined measures minimise the impact.",
      whenRequired: "Erforderlich sofort nach Bestätigung eines Sicherheitsvorfalls.",
      whenRequiredEn: "Required immediately after confirmation of a security incident.",
      sources: ["NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1", "ISO 27001:2022 A.5.26"] },

    { id: "p32-c03", title: "Bereinigung und Wiederherstellung", titleEn: "Eradication & Recovery",
      description: "Nach erfolgreicher Eindämmung müssen die Bedrohung vollständig entfernt und betroffene Systeme wiederhergestellt werden. Die Bereinigung umfasst: Entfernung von Malware/Backdoors, Schließen der ausgenutzten Schwachstelle, Reset aller potenziell kompromittierten Credentials, Neuinstallation oder Wiederherstellung aus sauberen Backups bei schwerer Kompromittierung. Die Wiederherstellung erfolgt nach der priorisierten Reihenfolge kritischer Dienste.",
      descriptionEn: "After successful containment, the threat must be completely removed and affected systems restored. Eradication includes: removal of malware/backdoors, closing the exploited vulnerability, resetting all potentially compromised credentials, reinstallation or restoration from clean backups for severe compromise. Recovery follows the prioritised order of critical services.",
      reason: "Unvollständige Bereinigung ist die häufigste Ursache für erneute Kompromittierungen. Nur eine systematische und dokumentierte Bereinigung stellt sicher, dass die Bedrohung vollständig beseitigt ist.",
      reasonEn: "Incomplete eradication is the most common cause of re-compromise. Only systematic and documented eradication ensures the threat is completely eliminated.",
      whenRequired: "Erforderlich nach jeder erfolgreichen Eindämmung eines Sicherheitsvorfalls.",
      whenRequiredEn: "Required after every successful containment of a security incident.",
      sources: ["NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1", "ISO 27001:2022 A.5.26", "NIST CSF 2.0 RC"] },

    { id: "p32-c04", title: "Post-Incident-Überwachung", titleEn: "Post-Incident Monitoring",
      description: "Nach der Wiederherstellung muss eine verstärkte Überwachung der betroffenen und angrenzenden Systeme für mindestens 30 Tage durchgeführt werden. Spezifische Erkennungsregeln für die im Vorfall identifizierten Angriffstechniken müssen implementiert werden. Wiederholte Kompromittierungsindikatoren müssen sofort eskaliert werden. Die verstärkte Überwachung darf erst nach Freigabe durch den Incident Manager beendet werden.",
      descriptionEn: "After recovery, enhanced monitoring of affected and adjacent systems must be conducted for at least 30 days. Specific detection rules for the attack techniques identified in the incident must be implemented. Recurring compromise indicators must be immediately escalated. Enhanced monitoring may only be terminated with approval from the Incident Manager.",
      reason: "Angreifer kehren häufig zu ihren Zielen zurück, insbesondere wenn die initiale Kompromittierung nicht vollständig aufgeklärt wurde. Post-Incident-Überwachung erkennt erneute Angriffsversuche frühzeitig.",
      reasonEn: "Attackers frequently return to their targets, especially when the initial compromise was not fully investigated. Post-incident monitoring detects renewed attack attempts early.",
      whenRequired: "Erforderlich nach jeder Wiederherstellung von einem Sicherheitsvorfall.",
      whenRequiredEn: "Required after every recovery from a security incident.",
      sources: ["NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1", "ISO 27001:2022 A.5.26"] },

    { id: "p32-c05", title: "Vorfallabschluss und Abschlussbericht", titleEn: "Incident Closure & Final Report",
      description: "Jeder Sicherheitsvorfall muss formal abgeschlossen werden, wenn alle Maßnahmen abgeschlossen sind und keine Restrisiken bestehen. Ein Abschlussbericht muss erstellt werden, der den gesamten Verlauf, die durchgeführten Maßnahmen, die entstandenen Kosten und den Bereinigungsstatus dokumentiert. Der Abschluss muss durch den Incident Manager genehmigt werden. Die strategische Post-Incident-Review (Lessons Learned, Root-Cause-Analyse, Prozessverbesserungen) wird in p30-c07 geregelt; dieser Bericht liefert die operative Grundlage dafür.",
      descriptionEn: "Every security incident must be formally closed when all measures are completed and no residual risks remain. A final report must be created documenting the entire course, measures taken, costs incurred, and remediation status. Closure must be approved by the Incident Manager. The strategic post-incident review (lessons learned, root cause analysis, process improvements) is governed in p30-c07; this report provides the operational basis for it.",
      reason: "Ohne formalen Abschluss bleiben Vorfälle als offene Aufgaben bestehen. Der Abschlussbericht dokumentiert den operativen Verlauf und dient als Eingabe für die strategische Nachbereitung in p30-c07.",
      reasonEn: "Without formal closure, incidents remain as open tasks. The final report documents the operational course and serves as input for the strategic post-incident review in p30-c07.",
      whenRequired: "Erforderlich für jeden abgeschlossenen Sicherheitsvorfall.",
      whenRequiredEn: "Required for every completed security incident.",
      sources: ["ISO 27001:2022 A.5.27", "BSI IT-Grundschutz DER.2.1", "NIST SP 800-61r3"] },

    { id: "p32-c06", title: "Automatisierte Incident-Response-Aktionen", titleEn: "Automated Incident Response Actions",
      description: "Wir müssen SOAR (Security Orchestration, Automation and Response) oder vergleichbare Automatisierung implementieren, um Standardreaktionen zu beschleunigen. Automatisierbare Aktionen umfassen: IoC-Blockierung in Firewall/Proxy, Kontosperrung bei Brute-Force-Erkennung, Quarantäne infizierter Endpunkte, automatische Ticket-Erstellung und Benachrichtigung des IRT. Automatisierte Aktionen müssen protokolliert und regelmäßig überprüft werden.",
      descriptionEn: "We must implement SOAR (Security Orchestration, Automation and Response) or comparable automation to accelerate standard responses. Automatable actions include: IoC blocking in firewall/proxy, account lockout on brute-force detection, quarantine of infected endpoints, automatic ticket creation, and IRT notification. Automated actions must be logged and regularly reviewed.",
      reason: "Manuelle Reaktion auf jeden Vorfall skaliert nicht. Automatisierung verkürzt die Reaktionszeit und entlastet das IRT für komplexe Aufgaben.",
      reasonEn: "Manual response to every incident does not scale. Automation reduces response time and frees the IRT for complex tasks.",
      whenRequired: "Empfohlen für Organisationen mit hohem Vorfallvolumen.",
      whenRequiredEn: "Recommended for organisations with high incident volume.",
      sources: ["NIST CSF 2.0 RS.RP", "ISO 27001:2022 A.8.16", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p32-c07", title: "Operative Kommunikation während der Vorfallbehandlung", titleEn: "Operational Communication During Incident Handling",
      description: "Während der aktiven Vorfallbehandlung muss eine strukturierte operative Kommunikation gewährleistet sein. Status-Updates müssen in festgelegten Intervallen an definierte Stakeholder (betroffene Abteilungen, IRT-Mitglieder) kommuniziert werden. Ein dedizierter Kommunikationskanal (z.B. verschlüsselter Chat-Raum) muss für das IRT bereitstehen. Alle Kommunikation muss protokolliert und in den Vorfallbericht aufgenommen werden. Strategische Kommunikationsentscheidungen (externe Meldungen, Medien, Behörden) werden in p30-c06 geregelt.",
      descriptionEn: "During active incident handling, structured operational communication must be ensured. Status updates must be communicated to defined stakeholders (affected departments, IRT members) at defined intervals. A dedicated communication channel (e.g., encrypted chat room) must be available for the IRT. All communication must be logged and included in the incident report. Strategic communication decisions (external reporting, media, authorities) are governed in p30-c06.",
      reason: "Chaotische operative Kommunikation während eines Vorfalls führt zu Fehlinformationen und verzögerter Reaktion. Strukturierte Kanäle halten das IRT synchron.",
      reasonEn: "Chaotic operational communication during an incident leads to misinformation and delayed response. Structured channels keep the IRT synchronised.",
      whenRequired: "Erforderlich für alle Vorfälle ab Schweregrad P3.",
      whenRequiredEn: "Required for all incidents of severity P3 and above.",
      sources: ["ISO 27001:2022 A.5.25", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.CO"] },

    { id: "p32-c08", title: "Parallele Bedrohungssuche (Threat Hunting)", titleEn: "Parallel Threat Hunting",
      description: "Bei bestätigten Vorfällen muss parallel zur Eindämmung eine aktive Bedrohungssuche in der gesamten Infrastruktur durchgeführt werden. Ziel ist die Identifizierung weiterer kompromittierter Systeme, die möglicherweise noch nicht erkannt wurden. Threat Hunting muss auf den im Vorfall identifizierten TTPs (Tactics, Techniques, Procedures) und IoCs basieren. Ergebnisse müssen in den Vorfallbericht einfließen.",
      descriptionEn: "For confirmed incidents, active threat hunting must be conducted across the entire infrastructure in parallel with containment. The goal is identifying additional compromised systems that may not yet have been detected. Threat hunting must be based on the TTPs (Tactics, Techniques, Procedures) and IoCs identified in the incident. Results must feed into the incident report.",
      reason: "Angreifer kompromittieren oft mehrere Systeme gleichzeitig. Ohne aktive Bedrohungssuche werden Lateral-Movement-Aktivitäten möglicherweise nicht erkannt.",
      reasonEn: "Attackers often compromise multiple systems simultaneously. Without active threat hunting, lateral movement activities may go undetected.",
      whenRequired: "Erforderlich bei bestätigten Kompromittierungen ab Schweregrad P2.",
      whenRequiredEn: "Required for confirmed compromises of severity P2 and above.",
      sources: ["NIST CSF 2.0 DE.AE", "MITRE ATT&CK", "BSI IT-Grundschutz DER.1.1"] },

    { id: "p32-c09", title: "Operative Beweissicherungs-Workflows", titleEn: "Operational Evidence Collection Workflows",
      description: "Für die operative Durchführung der Beweissicherung müssen standardisierte Arbeitsabläufe definiert sein: Reihenfolge der Sicherung (RAM → Netzwerk → Festplatte), zuständige Rollen (First Responder vs. Forensik-Spezialist), Übergabeprotokolle zwischen Schichten und Teams, Speicherorte und Zugriffskontrollen für gesicherte Beweise und Integration in das Incident-Tracking-System. Die grundlegenden Standards der forensischen Beweissicherung (Chain of Custody, Hash-Werte, Gerichtsfestigkeit) werden in p30-c05 definiert.",
      descriptionEn: "Standardised workflows must be defined for operational evidence collection: collection sequence (RAM → network → disk), responsible roles (first responder vs. forensic specialist), handover protocols between shifts and teams, storage locations and access controls for collected evidence, and integration into the incident tracking system. The fundamental standards for forensic evidence preservation (chain of custody, hash values, court admissibility) are defined in p30-c05.",
      reason: "p30-c05 definiert die Prinzipien der Beweissicherung; diese Klausel regelt die operative Umsetzung im Tagesgeschäft — wer, wann, in welcher Reihenfolge und mit welchen Werkzeugen.",
      reasonEn: "p30-c05 defines evidence preservation principles; this clause governs the operational implementation in daily operations — who, when, in what order, and with which tools.",
      whenRequired: "Erforderlich bei allen Vorfällen mit potenziellem rechtlichem Nachspiel.",
      whenRequiredEn: "Required for all incidents with potential legal follow-up.",
      sources: ["ISO 27001:2022 A.5.28", "BSI IT-Grundschutz DER.2.2", "NIST SP 800-86"] },

    { id: "p32-c10", title: "Koordination mit betroffenen Abteilungen", titleEn: "Coordination with Affected Departments",
      description: "Die Vorfallbehandlung muss eine enge Koordination mit den betroffenen Fachabteilungen umfassen. Abteilungsleiter müssen über Auswirkungen und geplante Maßnahmen informiert werden. Abschaltungen oder Einschränkungen müssen vorab kommuniziert und deren geschäftliche Auswirkungen bewertet werden. Workaround-Lösungen für betroffene Geschäftsprozesse müssen gemeinsam entwickelt werden.",
      descriptionEn: "Incident handling must include close coordination with affected business departments. Department heads must be informed about impacts and planned measures. Shutdowns or restrictions must be communicated in advance and their business impacts assessed. Workaround solutions for affected business processes must be jointly developed.",
      reason: "Ohne Koordination mit Fachabteilungen können Maßnahmen des IRT unbeabsichtigt größere Geschäftsauswirkungen verursachen als der Vorfall selbst.",
      reasonEn: "Without coordination with business departments, IRT measures can unintentionally cause greater business impact than the incident itself.",
      whenRequired: "Erforderlich bei Vorfällen, die Geschäftsprozesse beeinträchtigen.",
      whenRequiredEn: "Required for incidents affecting business processes.",
      sources: ["ISO 27001:2022 A.5.25", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.CO"] },

    { id: "p32-c11", title: "Operative Ressourcenzuweisung und Teamsteuerung", titleEn: "Operational Resource Allocation & Team Management",
      description: "Ressourcen für die Vorfallbehandlung müssen operativ zugewiesen und gesteuert werden. P1-Vorfälle erhalten unbeschränkte Ressourcen mit sofortiger Verfügbarkeit des gesamten IRT. P2-Vorfälle erhalten dedizierte Analysten und Zugang zu externen Experten bei Bedarf. P3/P4-Vorfälle werden im regulären Betrieb bearbeitet. Bei konkurrierenden Vorfällen entscheidet der Incident Manager über die Priorisierung. Schichtpläne, Rotation und Burnout-Prävention bei Langzeit-Vorfällen müssen berücksichtigt werden. Die analytische Priorisierungsmatrix (Schweregrad × Schutzziel × Compliance-Impact), die die Grundlage für diese Zuweisung bildet, wird in p33-c20 definiert.",
      descriptionEn: "Resources for incident handling must be operationally allocated and managed. P1 incidents receive unlimited resources with immediate availability of the entire IRT. P2 incidents receive dedicated analysts and access to external experts as needed. P3/P4 incidents are handled in regular operations. For competing incidents, the Incident Manager decides on prioritisation. Shift schedules, rotation, and burnout prevention during long-duration incidents must be considered. The analytical prioritisation matrix (severity × protection goal × compliance impact) that forms the basis for this allocation is defined in p33-c20.",
      reason: "Begrenzte IRT-Ressourcen müssen operativ effizient eingesetzt werden. Diese Klausel regelt die konkrete Teamsteuerung; die analytische Priorisierungslogik liegt in p33-c20.",
      reasonEn: "Limited IRT resources must be operationally used efficiently. This clause governs concrete team management; the analytical prioritisation logic resides in p33-c20.",
      whenRequired: "Erforderlich als Grundlage für die Ressourcenplanung im Incident Management.",
      whenRequiredEn: "Required as basis for resource planning in incident management.",
      sources: ["ISO 27001:2022 A.5.24", "NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p32-c12", title: "Vorfallbehandlung in OT/ICS-Umgebungen", titleEn: "Incident Handling in OT/ICS Environments",
      description: "Für Vorfälle in OT (Operational Technology) und ICS (Industrial Control Systems) Umgebungen müssen spezifische Verfahren definiert sein. Besonderheiten umfassen: Safety-Aspekte haben Vorrang vor IT-Sicherheitsmaßnahmen, Netzwerksegmentierung zwischen IT und OT muss verstärkt werden, Patch- und Bereinigungsmaßnahmen erfordern Abstimmung mit Anlagenbetreibern, physische Sicherheit der Anlage muss gewährleistet sein.",
      descriptionEn: "For incidents in OT (Operational Technology) and ICS (Industrial Control Systems) environments, specific procedures must be defined. Particularities include: safety aspects take priority over IT security measures, network segmentation between IT and OT must be strengthened, patch and remediation measures require coordination with plant operators, physical safety of the facility must be ensured.",
      reason: "OT/ICS-Umgebungen haben grundlegend andere Anforderungen als klassische IT. Standard-IT-Incident-Response kann in OT-Umgebungen Safety-Risiken verursachen.",
      reasonEn: "OT/ICS environments have fundamentally different requirements than traditional IT. Standard IT incident response can cause safety risks in OT environments.",
      whenRequired: "Erforderlich für Organisationen mit OT/ICS-Infrastruktur.",
      whenRequiredEn: "Required for organisations with OT/ICS infrastructure.",
      sources: ["IEC 62443", "NIS2 Art.21", "BSI ICS Security Compendium", "NIST SP 800-82r3"] },

    { id: "p32-c13", title: "Ransomware-Spezialverfahren", titleEn: "Ransomware Special Procedures",
      description: "Für Ransomware-Vorfälle müssen dedizierte Verfahren definiert sein: sofortige Netzwerkisolierung aller betroffenen Segmente, Identifizierung der Ransomware-Variante, Prüfung auf verfügbare Entschlüsselungstools, Bewertung der Backup-Integrität, Entscheidungsmatrix für Lösegeldzahlung (grundsätzlich nicht empfohlen), koordinierte Wiederherstellung nach Priorität und Kommunikation mit Strafverfolgungsbehörden.",
      descriptionEn: "Dedicated procedures must be defined for ransomware incidents: immediate network isolation of all affected segments, identification of the ransomware variant, check for available decryption tools, assessment of backup integrity, decision matrix for ransom payment (generally not recommended), coordinated recovery by priority, and communication with law enforcement.",
      reason: "Ransomware ist die häufigste und teuerste Bedrohung. Spezifische Verfahren stellen sicher, dass keine kritischen Schritte ausgelassen werden und die Entscheidung über Lösegeldzahlung fundiert getroffen wird.",
      reasonEn: "Ransomware is the most common and expensive threat. Specific procedures ensure no critical steps are skipped and the ransom payment decision is made on informed grounds.",
      whenRequired: "Erforderlich für alle Organisationen als wahrscheinlichstes Angriffsszenario.",
      whenRequiredEn: "Required for all organisations as the most likely attack scenario.",
      sources: ["NIST SP 800-61r3", "BSI Ransomware Guidelines", "ENISA Ransomware Report", "NIST CSF 2.0 RS"] },

    { id: "p32-c14", title: "Supply-Chain-Incident-Verfahren", titleEn: "Supply Chain Incident Procedures",
      description: "Für Vorfälle in der Lieferkette müssen spezifische Verfahren definiert sein: Identifizierung aller betroffenen Produkte/Dienste, Kontaktaufnahme mit dem betroffenen Lieferanten, Bewertung des eigenen Expositionsgrads, Implementierung temporärer Schutzmaßnahmen, Überwachung auf Kompromittierungsindikatoren und Koordination der Wiederherstellung über die gesamte betroffene Lieferkette.",
      descriptionEn: "Specific procedures must be defined for supply chain incidents: identification of all affected products/services, contacting the affected supplier, assessment of own exposure level, implementation of temporary protective measures, monitoring for compromise indicators, and coordinating recovery across the entire affected supply chain.",
      reason: "Supply-Chain-Angriffe betreffen gleichzeitig viele Organisationen. Ohne spezifische Verfahren verzögert sich die Reaktion und der Schaden vergrößert sich.",
      reasonEn: "Supply chain attacks affect many organisations simultaneously. Without specific procedures, response is delayed and damage increases.",
      whenRequired: "Erforderlich als NIS2-Anforderung für alle regulierten Organisationen.",
      whenRequiredEn: "Required as NIS2 requirement for all regulated organisations.",
      sources: ["NIS2 Art.21(2)(d)", "ISO 27001:2022 A.5.19", "BSI IT-Grundschutz OPS.2.1"] },

    { id: "p32-c15", title: "Datenverlust- und Exfiltrationsverfahren", titleEn: "Data Loss & Exfiltration Procedures",
      description: "Bei Verdacht auf Datenverlust oder -exfiltration müssen spezifische Verfahren aktiviert werden: Identifizierung betroffener Datentypen und -mengen, Überprüfung von DLP-Logs und Netzwerk-Traffic, Bewertung der Auswirkungen auf betroffene Personen, Einleitung der DSGVO-Meldepflichten bei personenbezogenen Daten, Kommunikation mit betroffenen Dateneignern und Implementierung zusätzlicher Schutzmaßnahmen zur Verhinderung weiterer Exfiltration.",
      descriptionEn: "In case of suspected data loss or exfiltration, specific procedures must be activated: identification of affected data types and volumes, review of DLP logs and network traffic, assessment of impact on affected individuals, initiation of GDPR notification obligations for personal data, communication with affected data owners, and implementation of additional protective measures to prevent further exfiltration.",
      reason: "Datenverlust hat besondere regulatorische (DSGVO) und geschäftliche Implikationen. Spezifische Verfahren stellen sicher, dass alle Meldepflichten eingehalten und betroffene Personen geschützt werden.",
      reasonEn: "Data loss has particular regulatory (GDPR) and business implications. Specific procedures ensure all notification obligations are met and affected individuals are protected.",
      whenRequired: "Erforderlich bei jedem Verdacht auf Datenverlust oder -exfiltration.",
      whenRequiredEn: "Required for every suspicion of data loss or exfiltration.",
      sources: ["DSGVO Art.33-34", "ISO 27001:2022 A.5.26", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p32-c16", title: "Insider-Bedrohungs-Verfahren", titleEn: "Insider Threat Procedures",
      description: "Für Insider-Bedrohungen (böswillige oder fahrlässige Mitarbeitende) müssen spezifische Verfahren definiert sein: diskrete Untersuchung ohne Vorwarnung des Verdächtigen, Einbeziehung von HR und Rechtsabteilung, besondere Beweissicherungsanforderungen (arbeitsrechtliche Verwertbarkeit), schrittweiser Entzug von Berechtigungen, Berücksichtigung von Mitbestimmungsrechten und datenschutzrechtliche Anforderungen an die Überwachung.",
      descriptionEn: "Specific procedures must be defined for insider threats (malicious or negligent employees): discreet investigation without warning the suspect, involvement of HR and legal department, special evidence preservation requirements (employment law admissibility), gradual revocation of permissions, consideration of co-determination rights, and data protection requirements for monitoring.",
      reason: "Insider-Bedrohungen erfordern einen fundamentally anderen Ansatz als externe Angriffe, insbesondere hinsichtlich arbeitsrechtlicher und datenschutzrechtlicher Aspekte.",
      reasonEn: "Insider threats require a fundamentally different approach than external attacks, especially regarding employment law and data protection aspects.",
      whenRequired: "Erforderlich als spezifisches Verfahren im Incident Management.",
      whenRequiredEn: "Required as a specific procedure in incident management.",
      sources: ["ISO 27001:2022 A.6.4", "BSI IT-Grundschutz ORP.4", "NIST SP 800-61r3"] },

    { id: "p32-c17", title: "Business-Impact-Minimierung während Vorfällen", titleEn: "Business Impact Minimisation During Incidents",
      description: "Während der Vorfallbehandlung muss aktiv daran gearbeitet werden, die Auswirkungen auf den Geschäftsbetrieb zu minimieren. Für kritische Geschäftsprozesse müssen Workaround-Optionen vorbereitet sein. Die Balance zwischen Sicherheit (vollständige Eindämmung) und Geschäftskontinuität muss bewusst gesteuert werden. Entscheidungen über akzeptable Restrisiken während der Behandlung müssen von der Geschäftsleitung getroffen und dokumentiert werden.",
      descriptionEn: "During incident handling, active efforts must be made to minimise impacts on business operations. For critical business processes, workaround options must be prepared. The balance between security (complete containment) and business continuity must be consciously managed. Decisions about acceptable residual risks during handling must be made by executive management and documented.",
      reason: "Überzogene Sicherheitsmaßnahmen können mehr Schaden anrichten als der Vorfall selbst. Die Balance zwischen Sicherheit und Geschäftskontinuität muss aktiv gesteuert werden.",
      reasonEn: "Excessive security measures can cause more damage than the incident itself. The balance between security and business continuity must be actively managed.",
      whenRequired: "Erforderlich für alle Vorfälle, die Geschäftsprozesse beeinträchtigen.",
      whenRequiredEn: "Required for all incidents affecting business processes.",
      sources: ["ISO 27001:2022 A.5.29", "BSI IT-Grundschutz DER.4", "NIST CSF 2.0 RC.RP"] },

    { id: "p32-c18", title: "Root-Cause-Analyse (RCA)", titleEn: "Root Cause Analysis (RCA)",
      description: "Für jeden Vorfall ab Schweregrad P2 muss eine formale Root-Cause-Analyse durchgeführt werden. Methoden wie 5-Why, Ishikawa-Diagramm oder Fault-Tree-Analysis sollen angewandt werden. Die RCA muss nicht nur die technische Ursache, sondern auch organisatorische und prozessuale Faktoren identifizieren. Ergebnisse müssen in konkrete Verbesserungsmaßnahmen überführt und nachverfolgt werden.",
      descriptionEn: "For every incident of severity P2 and above, a formal root cause analysis must be conducted. Methods such as 5-Why, Ishikawa diagram, or fault tree analysis should be applied. The RCA must identify not only the technical cause but also organisational and procedural factors. Results must be translated into concrete improvement measures and tracked.",
      reason: "Ohne Ursachenanalyse werden nur Symptome behandelt. Nur eine fundierte RCA verhindert die Wiederholung desselben Vorfalls.",
      reasonEn: "Without root cause analysis, only symptoms are treated. Only a thorough RCA prevents recurrence of the same incident.",
      whenRequired: "Erforderlich für alle Vorfälle ab Schweregrad P2.",
      whenRequiredEn: "Required for all incidents of severity P2 and above.",
      sources: ["ISO 27001:2022 A.5.27", "NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p32-c19", title: "Vorfallbehandlung außerhalb der Geschäftszeiten", titleEn: "Incident Handling Outside Business Hours",
      description: "Für die Vorfallbehandlung außerhalb der regulären Geschäftszeiten müssen spezifische Verfahren definiert sein: Bereitschaftsregelungen mit klaren Erreichbarkeiten, reduzierte Besetzung mit Eskalationsmöglichkeit zum Vollteam, vorab genehmigte Sofortmaßnahmen für kritische Vorfälle ohne vorherige Management-Freigabe, Remote-Zugang zu Incident-Response-Werkzeugen und definierte Antwortzeiten für Bereitschaftspersonal.",
      descriptionEn: "Specific procedures must be defined for incident handling outside regular business hours: on-call arrangements with clear availability, reduced staffing with escalation capability to full team, pre-approved immediate measures for critical incidents without prior management approval, remote access to incident response tools, and defined response times for on-call personnel.",
      reason: "Angreifer operieren bevorzugt außerhalb der Geschäftszeiten. Ohne definierte Bereitschaftsregelungen kann die Reaktion um Stunden verzögert werden.",
      reasonEn: "Attackers preferably operate outside business hours. Without defined on-call arrangements, response can be delayed by hours.",
      whenRequired: "Erforderlich für Organisationen mit 24/7-Betrieb oder kritischer Infrastruktur.",
      whenRequiredEn: "Required for organisations with 24/7 operations or critical infrastructure.",
      sources: ["NIS2 Art.21(2)(b)", "ISO 27001:2022 A.5.24", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p32-c20", title: "Multi-Incident-Management", titleEn: "Multi-Incident Management",
      description: "Verfahren müssen definiert sein für die gleichzeitige Bearbeitung mehrerer Sicherheitsvorfälle. Priorisierungskriterien müssen festgelegt sein, wenn Ressourcen nicht für alle Vorfälle gleichzeitig ausreichen. Die Möglichkeit, dass mehrere Vorfälle zusammenhängen (koordinierter Angriff), muss systematisch geprüft werden. Temporäre Ressourcenverstärkung durch externe Experten muss vorgesehen sein.",
      descriptionEn: "Procedures must be defined for simultaneous handling of multiple security incidents. Prioritisation criteria must be established when resources are insufficient for all incidents simultaneously. The possibility that multiple incidents are related (coordinated attack) must be systematically checked. Temporary resource reinforcement through external experts must be provided for.",
      reason: "Bei koordinierten Angriffen treten häufig mehrere Vorfälle gleichzeitig auf. Ohne Multi-Incident-Verfahren droht die Überlastung des IRT.",
      reasonEn: "In coordinated attacks, multiple incidents often occur simultaneously. Without multi-incident procedures, the IRT risks being overwhelmed.",
      whenRequired: "Erforderlich als Skalierungsfähigkeit des Incident Managements.",
      whenRequiredEn: "Required as scalability capability of incident management.",
      sources: ["NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1", "ISO 27001:2022 A.5.24"] },

    { id: "p32-c21", title: "Operatives Wissensmanagement und Playbook-Aktualisierung", titleEn: "Operational Knowledge Management & Playbook Updates",
      description: "Operative Erkenntnisse aus Vorfällen müssen systematisch in die Handlungsverfahren zurückfließen. Playbooks, Checklisten und Entscheidungsbäume müssen nach jedem signifikanten Vorfall aktualisiert werden. Ein durchsuchbares Knowledge-Base-System muss vergangene Vorfälle, angewandte Lösungen und erkannte Fehlermuster für das IRT bereitstellen. Neue Erkenntnisse müssen in die nächste Schulungsiteration aufgenommen werden. Die strategische Post-Incident-Review (Lessons-Learned-Sitzung, Ursachenanalyse, Prozessverbesserungen) wird in p30-c07 geregelt und liefert die Eingaben für diese operative Integration.",
      descriptionEn: "Operational insights from incidents must systematically feed back into handling procedures. Playbooks, checklists, and decision trees must be updated after every significant incident. A searchable knowledge base system must provide past incidents, applied solutions, and recognised error patterns for the IRT. New insights must be included in the next training iteration. The strategic post-incident review (lessons learned session, root cause analysis, process improvements) is governed in p30-c07 and provides the inputs for this operational integration.",
      reason: "p30-c07 definiert die strategische Nachbereitung; diese Klausel regelt die operative Umsetzung — Playbook-Pflege, Knowledge-Base und Schulungsintegration.",
      reasonEn: "p30-c07 defines the strategic post-incident review; this clause governs the operational implementation — playbook maintenance, knowledge base, and training integration.",
      whenRequired: "Erforderlich als Teil des kontinuierlichen Verbesserungsprozesses.",
      whenRequiredEn: "Required as part of the continuous improvement process.",
      sources: ["ISO 27001:2022 A.5.27", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.IM"] },

    { id: "p32-c22", title: "Überprüfung der Incident-Handling-Verfahren", titleEn: "Review of Incident Handling Procedures",
      description: "Die Verfahren zur Vorfallbehandlung müssen mindestens jährlich und nach jedem signifikanten Vorfall überprüft und aktualisiert werden. Die Überprüfung muss die Wirksamkeit der Verfahren, die Aktualität der Kontaktlisten, die Verfügbarkeit der Werkzeuge und die Kompetenzen des Teams bewerten. Ergebnisse der Überprüfung müssen dokumentiert und an die Geschäftsleitung berichtet werden.",
      descriptionEn: "Incident handling procedures must be reviewed and updated at least annually and after every significant incident. The review must evaluate effectiveness of procedures, currency of contact lists, availability of tools, and team competencies. Review results must be documented and reported to executive management.",
      reason: "Veraltete Verfahren sind im Ernstfall unwirksam. Regelmäßige Überprüfung stellt sicher, dass alle Verfahren aktuell, praktikabel und wirksam sind.",
      reasonEn: "Outdated procedures are ineffective in real situations. Regular review ensures all procedures are current, practicable, and effective.",
      whenRequired: "Immer erforderlich als Teil des ISMS-Regelkreises.",
      whenRequiredEn: "Always required as part of the ISMS cycle.",
      sources: ["ISO 27001:2022 §10.1-10.2", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.IM"] },
  ],

  // ═══════════════════════════════════════════════════════════════
  // P33 — Incident Classification & Severity Policy
  // ═══════════════════════════════════════════════════════════════
  p33: [
    { id: "p33-c00", title: "Schweregrad-Definitionen", titleEn: "Severity Level Definitions",
      description: "Wir müssen klare Schweregrad-Stufen für Sicherheitsvorfälle definieren. Empfohlene Stufen: P1-Kritisch (existenzbedrohend, vollständige Kompromittierung, Ausfall kritischer Dienste), P2-Hoch (erheblicher Schaden, Datenverlust, betroffene Geschäftsprozesse), P3-Mittel (begrenzter Schaden, einzelne Systeme betroffen), P4-Niedrig (minimaler Impact, keine Datenverluste). Jede Stufe muss mit Beispielszenarien, Reaktionszeiten und Eskalationsregeln verknüpft sein.",
      descriptionEn: "We must define clear severity levels for security incidents. Recommended levels: P1-Critical (existential threat, complete compromise, critical service outage), P2-High (significant damage, data loss, affected business processes), P3-Medium (limited damage, individual systems affected), P4-Low (minimal impact, no data loss). Each level must be linked to example scenarios, response times, and escalation rules.",
      reason: "Ohne standardisierte Schweregrad-Definitionen werden Vorfälle inkonsistent bewertet und Ressourcen falsch priorisiert.",
      reasonEn: "Without standardised severity definitions, incidents are assessed inconsistently and resources are incorrectly prioritised.",
      whenRequired: "Immer erforderlich als Grundlage der Vorfallklassifizierung.",
      whenRequiredEn: "Always required as the foundation of incident classification.",
      sources: ["ISO 27001:2022 A.5.25", "NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p33-c01", title: "Vorfalltypen-Taxonomie", titleEn: "Incident Type Taxonomy",
      description: "Wir müssen eine Taxonomie für Vorfalltypen definieren, die eine einheitliche Klassifizierung ermöglicht. Kategorien umfassen mindestens: Malware/Ransomware, Phishing/Social Engineering, Denial of Service, unbefugter Zugriff, Datenverlust/-exfiltration, Insider-Bedrohung, Fehlkonfiguration, physischer Sicherheitsvorfall, Lieferketten-Kompromittierung und Schwachstellenausnutzung. Die Taxonomie muss mit branchenüblichen Standards (z.B. VERIS) kompatibel sein.",
      descriptionEn: "We must define a taxonomy for incident types enabling uniform classification. Categories must include at minimum: malware/ransomware, phishing/social engineering, denial of service, unauthorised access, data loss/exfiltration, insider threat, misconfiguration, physical security incident, supply chain compromise, and vulnerability exploitation. The taxonomy must be compatible with industry standards (e.g., VERIS).",
      reason: "Ohne einheitliche Taxonomie werden Vorfälle unterschiedlich kategorisiert, was Trendanalysen und Vergleiche unmöglich macht.",
      reasonEn: "Without a uniform taxonomy, incidents are categorised differently, making trend analyses and comparisons impossible.",
      whenRequired: "Erforderlich für alle Organisationen mit strukturiertem Vorfallmanagement.",
      whenRequiredEn: "Required for all organisations with structured incident management.",
      sources: ["ISO 27001:2022 A.5.25", "VERIS Framework", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.AN"] },

    { id: "p33-c02", title: "Impact-Bewertungskriterien", titleEn: "Impact Assessment Criteria",
      description: "Die Auswirkungsbewertung muss anhand definierter Kriterien erfolgen: Vertraulichkeit (Art und Menge betroffener Daten), Integrität (Ausmaß der Manipulation), Verfügbarkeit (Dauer und Umfang des Ausfalls), finanzieller Schaden (direkte Kosten, Umsatzverlust), Reputationsschaden (öffentliche Wahrnehmung), regulatorischer Impact (Meldepflichten, Bußgeldrisiko) und Anzahl betroffener Personen/Systeme. Die Bewertung muss reproduzierbar und dokumentiert sein.",
      descriptionEn: "Impact assessment must follow defined criteria: confidentiality (type and volume of affected data), integrity (extent of manipulation), availability (duration and scope of outage), financial damage (direct costs, revenue loss), reputational damage (public perception), regulatory impact (reporting obligations, fine risk), and number of affected persons/systems. Assessment must be reproducible and documented.",
      reason: "Subjektive Impact-Bewertungen führen zu inkonsistenter Priorisierung. Standardisierte Kriterien stellen objektive und vergleichbare Bewertungen sicher.",
      reasonEn: "Subjective impact assessments lead to inconsistent prioritisation. Standardised criteria ensure objective and comparable assessments.",
      whenRequired: "Erforderlich für die Bewertung jedes Sicherheitsvorfalls.",
      whenRequiredEn: "Required for the assessment of every security incident.",
      sources: ["ISO 27001:2022 A.5.25", "BSI IT-Grundschutz DER.2.1", "NIST SP 800-61r3"] },

    { id: "p33-c03", title: "Reaktionszeiten nach Schweregrad (SLA)", titleEn: "Response Times by Severity (SLA)",
      description: "Für jeden Schweregrad müssen verbindliche Reaktionszeiten definiert sein: P1-Kritisch: Beginn der Bearbeitung innerhalb von 15 Minuten, Erstbewertung innerhalb von 1 Stunde, Eindämmung innerhalb von 4 Stunden. P2-Hoch: Beginn innerhalb von 1 Stunde, Erstbewertung innerhalb von 4 Stunden. P3-Mittel: Beginn innerhalb von 4 Stunden, Erstbewertung am nächsten Arbeitstag. P4-Niedrig: Beginn innerhalb eines Arbeitstages. Die Einhaltung muss überwacht und berichtet werden.",
      descriptionEn: "Binding response times must be defined for each severity: P1-Critical: start handling within 15 minutes, initial assessment within 1 hour, containment within 4 hours. P2-High: start within 1 hour, initial assessment within 4 hours. P3-Medium: start within 4 hours, initial assessment next business day. P4-Low: start within one business day. Compliance must be monitored and reported.",
      reason: "Ohne definierte Reaktionszeiten fehlt die Dringlichkeit und Verbindlichkeit bei der Vorfallbearbeitung. SLAs schaffen messbare Erwartungen und Accountability.",
      reasonEn: "Without defined response times, urgency and accountability in incident handling are lacking. SLAs create measurable expectations and accountability.",
      whenRequired: "Erforderlich für alle Schweregrad-Stufen.",
      whenRequiredEn: "Required for all severity levels.",
      sources: ["ISO 27001:2022 A.5.26", "NIS2 Art.23", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p33-c04", title: "Dynamische Neubewertung des Schweregrads", titleEn: "Dynamic Severity Re-Assessment",
      description: "Der Schweregrad eines Vorfalls muss bei neuen Erkenntnissen dynamisch angepasst werden können. Eine Hochstufung (z.B. von P3 auf P1) muss erfolgen, wenn sich der Umfang als größer herausstellt oder neue Systeme betroffen sind. Eine Herabstufung ist möglich, wenn sich die initiale Einschätzung als überzogen herausstellt. Jede Neubewertung muss dokumentiert und begründet werden. Die Eskalationsregeln der neuen Stufe gelten sofort.",
      descriptionEn: "The severity of an incident must be dynamically adjustable when new findings emerge. An upgrade (e.g., from P3 to P1) must occur when the scope proves larger or new systems are affected. A downgrade is possible when the initial assessment proves excessive. Every re-assessment must be documented and justified. Escalation rules of the new level apply immediately.",
      reason: "Die initiale Schweregrad-Einschätzung basiert häufig auf unvollständigen Informationen. Dynamische Neubewertung stellt sicher, dass Ressourcen immer angemessen zugewiesen sind.",
      reasonEn: "The initial severity assessment is frequently based on incomplete information. Dynamic re-assessment ensures resources are always appropriately allocated.",
      whenRequired: "Erforderlich als kontinuierlicher Prozess während der Vorfallbearbeitung.",
      whenRequiredEn: "Required as a continuous process during incident handling.",
      sources: ["NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1", "ISO 27001:2022 A.5.25"] },

    { id: "p33-c05", title: "Kriterien für die Meldepflicht-Bestimmung", titleEn: "Criteria for Reporting Obligation Determination",
      description: "Wir müssen klare Klassifizierungskriterien definieren, anhand derer bestimmt wird, ob ein Vorfall extern meldepflichtig ist (NIS2, DSGVO, branchenspezifische Regulierung). Die Kriterien umfassen: Schwellenwerte für betroffene Datensätze, Dauer der Dienstunterbrechung, Art der kompromittierten Systeme und ob personenbezogene Daten betroffen sind. Im Zweifelsfall ist immer eine Meldung vorzunehmen. Die daraus resultierenden Melde-Workflows und operativen Fristen werden in p31 geregelt.",
      descriptionEn: "We must define clear classification criteria for determining whether an incident is externally reportable (NIS2, GDPR, sector-specific regulation). Criteria include: thresholds for affected data records, duration of service interruption, type of compromised systems, and whether personal data is affected. In case of doubt, a report must always be filed. The resulting reporting workflows and operational deadlines are governed in p31.",
      reason: "Diese Klausel definiert die analytischen Kriterien für die Meldepflicht-Entscheidung; die operative Umsetzung der Meldung (Fristen, Formulare, Kanäle) liegt bei p31.",
      reasonEn: "This clause defines the analytical criteria for the reporting obligation decision; the operational implementation of reporting (deadlines, forms, channels) resides in p31.",
      whenRequired: "Erforderlich für alle Sicherheitsvorfälle bei NIS2-regulierten Organisationen.",
      whenRequiredEn: "Required for all security incidents at NIS2-regulated organisations.",
      sources: ["NIS2 Art.23", "DSGVO Art.33", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p33-c06", title: "Vorfallstatistiken und Trendanalyse", titleEn: "Incident Statistics & Trend Analysis",
      description: "Wir müssen regelmäßig (mindestens vierteljährlich) Statistiken über Sicherheitsvorfälle erstellen und Trends analysieren. Metriken umfassen: Anzahl der Vorfälle nach Typ und Schweregrad, durchschnittliche Erkennungs- und Reaktionszeiten, wiederkehrende Ursachen, betroffene Systeme/Abteilungen und Entwicklung über Zeit. Trendanalysen müssen zur Identifizierung systemischer Schwächen und zur Priorisierung von Verbesserungsmaßnahmen genutzt werden.",
      descriptionEn: "We must regularly (at least quarterly) create statistics on security incidents and analyse trends. Metrics include: number of incidents by type and severity, average detection and response times, recurring causes, affected systems/departments, and development over time. Trend analyses must be used to identify systemic weaknesses and prioritise improvement measures.",
      reason: "Ohne statistische Analyse bleiben Muster und systemische Schwächen unsichtbar. Trendanalysen ermöglichen proaktive Maßnahmen statt nur reaktiver Vorfallbearbeitung.",
      reasonEn: "Without statistical analysis, patterns and systemic weaknesses remain invisible. Trend analyses enable proactive measures instead of only reactive incident handling.",
      whenRequired: "Erforderlich als Teil des kontinuierlichen Verbesserungsprozesses.",
      whenRequiredEn: "Required as part of the continuous improvement process.",
      sources: ["ISO 27001:2022 §9.1", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.IM"] },

    { id: "p33-c07", title: "Klassifizierung nach betroffenen Schutzzielen", titleEn: "Classification by Affected Protection Goals",
      description: "Vorfälle müssen nach den betroffenen Schutzzielen klassifiziert werden: Vertraulichkeit (unbefugte Offenlegung), Integrität (unbefugte Veränderung), Verfügbarkeit (Dienst- oder Systemausfall) und Authentizität (Identitätsmissbrauch). Ein Vorfall kann mehrere Schutzziele gleichzeitig betreffen. Die Klassifizierung beeinflusst die Auswahl der Reaktionsmaßnahmen und die Meldepflichten.",
      descriptionEn: "Incidents must be classified by affected protection goals: confidentiality (unauthorised disclosure), integrity (unauthorised modification), availability (service or system outage), and authenticity (identity abuse). An incident can affect multiple protection goals simultaneously. Classification influences the selection of response measures and reporting obligations.",
      reason: "Die betroffenen Schutzziele bestimmen die Art der notwendigen Reaktion und die regulatorischen Meldepflichten. Eine klare Zuordnung ermöglicht zielgerichtete Maßnahmen.",
      reasonEn: "The affected protection goals determine the type of response needed and regulatory reporting obligations. Clear assignment enables targeted measures.",
      whenRequired: "Erforderlich für die Klassifizierung jedes Sicherheitsvorfalls.",
      whenRequiredEn: "Required for the classification of every security incident.",
      sources: ["ISO 27001:2022 A.5.25", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.AN"] },

    { id: "p33-c08", title: "Branchenspezifische Klassifizierungskriterien", titleEn: "Sector-Specific Classification Criteria",
      description: "Neben allgemeinen Klassifizierungskriterien müssen branchenspezifische Anforderungen berücksichtigt werden. Für KRITIS-Betreiber gelten besondere Schwellenwerte für meldepflichtige Vorfälle. Finanzdienstleister müssen DORA-Anforderungen beachten. Gesundheitsorganisationen müssen Patientensicherheitsaspekte berücksichtigen. Die branchenspezifischen Kriterien müssen in die Klassifizierungsmatrix integriert sein.",
      descriptionEn: "In addition to general classification criteria, sector-specific requirements must be considered. Critical infrastructure operators have special thresholds for reportable incidents. Financial service providers must comply with DORA requirements. Healthcare organisations must consider patient safety aspects. Sector-specific criteria must be integrated into the classification matrix.",
      reason: "Verschiedene Branchen haben unterschiedliche regulatorische Anforderungen und Risikoprofile. Eine universelle Klassifizierung berücksichtigt branchenspezifische Besonderheiten nicht ausreichend.",
      reasonEn: "Different sectors have different regulatory requirements and risk profiles. A universal classification does not sufficiently consider sector-specific particularities.",
      whenRequired: "Erforderlich für Organisationen in regulierten Branchen.",
      whenRequiredEn: "Required for organisations in regulated sectors.",
      sources: ["NIS2 Art.21", "BSI KRITIS-Verordnung", "DORA", "NIST CSF 2.0"] },

    { id: "p33-c09", title: "Automatische Klassifizierungsunterstützung", titleEn: "Automated Classification Support",
      description: "Technische Systeme (SIEM, SOAR) sollen die initiale Klassifizierung von Vorfällen automatisch unterstützen. Regelbasierte Klassifizierung muss für bekannte Vorfalltypen implementiert sein. Machine-Learning-basierte Anomalieerkennung kann die Schweregrad-Einschätzung unterstützen. Automatische Klassifizierungen müssen immer durch einen Analysten validiert werden, bevor sie als endgültig gelten.",
      descriptionEn: "Technical systems (SIEM, SOAR) should automatically support the initial classification of incidents. Rule-based classification must be implemented for known incident types. Machine learning-based anomaly detection can support severity assessment. Automatic classifications must always be validated by an analyst before being considered final.",
      reason: "Manuelle Klassifizierung ist bei hohem Vorfallvolumen zu langsam und inkonsistent. Automatisierte Unterstützung beschleunigt die Triage und verbessert die Konsistenz.",
      reasonEn: "Manual classification is too slow and inconsistent at high incident volumes. Automated support accelerates triage and improves consistency.",
      whenRequired: "Empfohlen für Organisationen mit hohem Vorfallvolumen oder SIEM-Infrastruktur.",
      whenRequiredEn: "Recommended for organisations with high incident volume or SIEM infrastructure.",
      sources: ["ISO 27001:2022 A.8.16", "NIST CSF 2.0 DE.AE", "BSI IT-Grundschutz DER.1.1"] },

    { id: "p33-c10", title: "Mehrfachklassifizierung und Vorfallketten", titleEn: "Multiple Classification & Incident Chains",
      description: "Verfahren müssen definiert sein für Vorfälle, die sich entwickeln oder mit anderen Vorfällen zusammenhängen. Ein einzelner Vorfall kann seinen Typ oder Schweregrad ändern (z.B. Phishing → kompromittiertes Konto → Datenexfiltration). Zusammenhängende Vorfälle müssen als Vorfallkette erkannt und zusammen bewertet werden. Der Gesamtschweregrad einer Kette kann höher sein als der einzelner Vorfälle.",
      descriptionEn: "Procedures must be defined for incidents that evolve or are related to other incidents. A single incident can change its type or severity (e.g., phishing → compromised account → data exfiltration). Related incidents must be recognised as an incident chain and assessed together. The overall severity of a chain may be higher than that of individual incidents.",
      reason: "Isolierte Bewertung zusammenhängender Vorfälle unterschätzt den tatsächlichen Schaden und die Bedrohung. Vorfallketten müssen ganzheitlich betrachtet werden.",
      reasonEn: "Isolated assessment of related incidents underestimates actual damage and threat. Incident chains must be viewed holistically.",
      whenRequired: "Erforderlich als Teil der Vorfallbewertung.",
      whenRequiredEn: "Required as part of incident assessment.",
      sources: ["NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1", "MITRE ATT&CK"] },

    { id: "p33-c11", title: "Klassifizierungsschulung für IRT-Mitglieder", titleEn: "Classification Training for IRT Members",
      description: "Alle IRT-Mitglieder müssen in der korrekten Anwendung des Klassifizierungssystems geschult werden. Schulungen müssen die Schweregrad-Definitionen, die Taxonomie, die Entscheidungsmatrix und Übungsszenarien umfassen. Regelmäßige Kalibrierungsübungen müssen sicherstellen, dass verschiedene Analysten dieselben Vorfälle konsistent klassifizieren. Klassifizierungsfehler aus realen Vorfällen müssen als Lernbeispiele genutzt werden.",
      descriptionEn: "All IRT members must be trained in the correct application of the classification system. Training must cover severity definitions, taxonomy, decision matrix, and practice scenarios. Regular calibration exercises must ensure different analysts consistently classify the same incidents. Classification errors from real incidents must be used as learning examples.",
      reason: "Inkonsistente Klassifizierung durch verschiedene Analysten führt zu ungleichmäßiger Reaktion. Regelmäßige Kalibrierung stellt konsistente Bewertungen sicher.",
      reasonEn: "Inconsistent classification by different analysts leads to uneven response. Regular calibration ensures consistent assessments.",
      whenRequired: "Erforderlich für alle IRT-Mitglieder.",
      whenRequiredEn: "Required for all IRT members.",
      sources: ["ISO 27001:2022 A.6.3", "NIST SP 800-61r3", "BSI IT-Grundschutz ORP.3"] },

    { id: "p33-c12", title: "Klassifizierung nach Angriffsvektor", titleEn: "Classification by Attack Vector",
      description: "Vorfälle müssen zusätzlich nach dem verwendeten Angriffsvektor klassifiziert werden: extern/remote (Internet-basiert), intern (aus dem internen Netzwerk), physisch (physischer Zugang), Lieferkette (über Drittanbieter), Social Engineering (menschliche Manipulation) und technische Schwachstelle (Exploit). Die Angriffsvektor-Klassifizierung unterstützt die Trendanalyse und die Priorisierung von Schutzmaßnahmen.",
      descriptionEn: "Incidents must additionally be classified by the attack vector used: external/remote (Internet-based), internal (from internal network), physical (physical access), supply chain (via third party), social engineering (human manipulation), and technical vulnerability (exploit). Attack vector classification supports trend analysis and prioritisation of protective measures.",
      reason: "Die Kenntnis der häufigsten Angriffsvektoren ermöglicht gezielte Investitionen in Schutzmaßnahmen und die Anpassung der Verteidigungsstrategie.",
      reasonEn: "Knowledge of the most common attack vectors enables targeted investment in protective measures and adaptation of the defence strategy.",
      whenRequired: "Erforderlich als erweiterte Klassifizierungsdimension.",
      whenRequiredEn: "Required as an extended classification dimension.",
      sources: ["MITRE ATT&CK", "VERIS Framework", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.AN"] },

    { id: "p33-c13", title: "Bewertung der Wiederholungswahrscheinlichkeit", titleEn: "Recurrence Probability Assessment",
      description: "Bei der Klassifizierung muss die Wahrscheinlichkeit einer Wiederholung des Vorfalls bewertet werden. Faktoren umfassen: wurde die Grundursache behoben, existieren ähnliche Schwachstellen in anderen Systemen, handelt es sich um eine systematische Schwäche oder einen Einzelfall, ist der Angreifer bekannt für wiederholte Angriffe. Die Wiederholungswahrscheinlichkeit beeinflusst die Priorisierung von Gegenmaßnahmen.",
      descriptionEn: "During classification, the probability of incident recurrence must be assessed. Factors include: whether the root cause was fixed, whether similar vulnerabilities exist in other systems, whether it is a systematic weakness or isolated case, and whether the attacker is known for repeated attacks. Recurrence probability influences prioritisation of countermeasures.",
      reason: "Ein Vorfall, der sich wahrscheinlich wiederholt, erfordert sofortige und umfassende Gegenmaßnahmen. Die Bewertung der Wiederholungswahrscheinlichkeit optimiert den Einsatz begrenzter Ressourcen.",
      reasonEn: "An incident likely to recur requires immediate and comprehensive countermeasures. Assessing recurrence probability optimises the use of limited resources.",
      whenRequired: "Empfohlen als Teil der erweiterten Vorfallbewertung.",
      whenRequiredEn: "Recommended as part of the extended incident assessment.",
      sources: ["ISO 27001:2022 A.5.27", "NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p33-c14", title: "NIS2-Erheblichkeitsschwellen und Quantifizierung", titleEn: "NIS2 Significance Thresholds & Quantification",
      description: "Wir müssen die NIS2-Erheblichkeitsschwellen für meldepflichtige Vorfälle klar definieren, quantifizieren und dokumentieren. Ein Vorfall gilt als erheblich, wenn er: schwerwiegende Betriebsstörungen oder finanzielle Verluste verursachen kann, andere natürliche oder juristische Personen durch erhebliche materielle oder immaterielle Schäden beeinträchtigen kann. Für jeden Schwellentyp müssen messbare Grenzwerte definiert sein (z.B. >X betroffene Nutzer, >Y Stunden Ausfall, >Z€ Schaden). Die hier definierten Schwellenwerte bilden die Grundlage für die operativen Meldefristen und -workflows in p31-c02.",
      descriptionEn: "We must clearly define, quantify, and document NIS2 significance thresholds for reportable incidents. An incident is considered significant if it: can cause serious operational disruption or financial losses, can affect other natural or legal persons through considerable material or immaterial damage. For each threshold type, measurable limits must be defined (e.g., >X affected users, >Y hours downtime, >Z€ damage). The thresholds defined here form the basis for the operational reporting deadlines and workflows in p31-c02.",
      reason: "NIS2 verwendet den Begriff 'erheblicher Vorfall' ohne exakte Quantifizierung. Diese Klausel ist die zentrale Referenz für Erheblichkeitsschwellen; p31-c02 regelt die daraus resultierenden Meldefristen.",
      reasonEn: "NIS2 uses the term 'significant incident' without exact quantification. This clause is the central reference for significance thresholds; p31-c02 governs the resulting reporting deadlines.",
      whenRequired: "Verpflichtend für alle NIS2-regulierten Organisationen.",
      whenRequiredEn: "Mandatory for all NIS2-regulated organisations.",
      sources: ["NIS2 Art.23(3)", "NIS2 Art.6(6)", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p33-c15", title: "Compliance-Impact-Dimension", titleEn: "Compliance Impact Dimension",
      description: "Die Klassifizierung muss eine dedizierte Compliance-Impact-Dimension enthalten. Diese bewertet: welche regulatorischen Meldepflichten ausgelöst werden (NIS2, DSGVO, KRITIS, sektorspezifisch), welche vertraglichen Pflichten betroffen sind, ob Zertifizierungen gefährdet sind, und welche Bußgeldrisiken bestehen. Die Compliance-Bewertung muss automatisch die entsprechenden Melde-Workflows auslösen.",
      descriptionEn: "Classification must include a dedicated compliance impact dimension. This assesses: which regulatory reporting obligations are triggered (NIS2, GDPR, KRITIS, sector-specific), which contractual obligations are affected, whether certifications are jeopardised, and what fine risks exist. The compliance assessment must automatically trigger the corresponding reporting workflows.",
      reason: "Compliance-Aspekte werden bei der Vorfallklassifizierung häufig übersehen. Eine dedizierte Dimension stellt sicher, dass regulatorische Pflichten nicht versäumt werden.",
      reasonEn: "Compliance aspects are frequently overlooked in incident classification. A dedicated dimension ensures regulatory obligations are not missed.",
      whenRequired: "Erforderlich für alle NIS2- und DSGVO-regulierten Organisationen.",
      whenRequiredEn: "Required for all NIS2 and GDPR-regulated organisations.",
      sources: ["NIS2 Art.23", "DSGVO Art.33-34", "ISO 27001:2022 A.5.25"] },

    { id: "p33-c16", title: "Überprüfung und Aktualisierung des Klassifizierungssystems", titleEn: "Review & Update of Classification System",
      description: "Das gesamte Klassifizierungssystem (Schweregrade, Taxonomie, Kriterien, Schwellenwerte) und diese Richtlinie müssen mindestens jährlich und nach signifikanten Vorfällen oder regulatorischen Änderungen überprüft und aktualisiert werden. Die Überprüfung muss prüfen: ob die Schweregrad-Definitionen noch angemessen sind, ob neue Vorfalltypen hinzugefügt werden müssen, ob die Reaktionszeiten realistisch sind, ob die regulatorischen Schwellenwerte aktuell sind und ob Erfahrungen aus realen Vorfällen Änderungen erfordern. Alle Änderungen müssen genehmigt, dokumentiert, an das IRT sowie relevante Stakeholder kommuniziert und geschult werden.",
      descriptionEn: "The entire classification system (severity levels, taxonomy, criteria, thresholds) and this policy must be reviewed and updated at least annually and after significant incidents or regulatory changes. The review must check: whether severity definitions are still appropriate, whether new incident types need to be added, whether response times are realistic, whether regulatory thresholds are current, and whether experiences from real incidents require changes. All changes must be approved, documented, communicated to the IRT and relevant stakeholders, and trained.",
      reason: "Ein veraltetes Klassifizierungssystem führt zu Fehlklassifizierungen und inadäquater Reaktion. Regelmäßige Überprüfung stellt die Aktualität und Angemessenheit sicher.",
      reasonEn: "An outdated classification system leads to misclassifications and inadequate response. Regular review ensures currency and appropriateness.",
      whenRequired: "Immer erforderlich als Teil des ISMS-Regelkreises.",
      whenRequiredEn: "Always required as part of the ISMS cycle.",
      sources: ["ISO 27001:2022 §10.1-10.2", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.IM"] },

    { id: "p33-c17", title: "Entscheidungsbaum für die Erstklassifizierung", titleEn: "Decision Tree for Initial Classification",
      description: "Ein visueller Entscheidungsbaum muss erstellt werden, der IRT-Analysten durch die Erstklassifizierung führt. Der Baum muss Fragen umfassen wie: Sind personenbezogene Daten betroffen? Sind kritische Dienste beeinträchtigt? Ist der Angreifer noch aktiv? Besteht Gefahr für weitere Systeme? Jede Antwort führt zur nächsten Frage oder zu einer vorläufigen Klassifizierung. Der Entscheidungsbaum muss in das Ticketsystem integriert oder als ausdruckbares Poster verfügbar sein.",
      descriptionEn: "A visual decision tree must be created to guide IRT analysts through initial classification. The tree must include questions such as: Are personal data affected? Are critical services impacted? Is the attacker still active? Is there risk to additional systems? Each answer leads to the next question or a preliminary classification. The decision tree must be integrated into the ticket system or available as a printable poster.",
      reason: "Unter dem Druck eines laufenden Vorfalls hilft ein strukturierter Entscheidungsbaum, konsistente und korrekte Klassifizierungen vorzunehmen, auch unter Stress.",
      reasonEn: "Under the pressure of an ongoing incident, a structured decision tree helps make consistent and correct classifications, even under stress.",
      whenRequired: "Empfohlen für alle Organisationen mit strukturiertem Incident Management.",
      whenRequiredEn: "Recommended for all organisations with structured incident management.",
      sources: ["NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1", "ISO 27001:2022 A.5.25"] },

    { id: "p33-c18", title: "Mapping zu externen Klassifizierungsstandards", titleEn: "Mapping to External Classification Standards",
      description: "Das interne Klassifizierungssystem muss mit externen Standards und Frameworks kompatibel sein. Mappings müssen erstellt werden zu: MITRE ATT&CK (Taktiken und Techniken), VERIS (Vocabulary for Event Recording), CVSSv4 (für Schwachstellen-bezogene Vorfälle), Traffic Light Protocol (TLP) für den Informationsaustausch und nationale CERT-Klassifizierungsschemata. Die Mappings ermöglichen standardisierten Informationsaustausch mit externen Stellen.",
      descriptionEn: "The internal classification system must be compatible with external standards and frameworks. Mappings must be created to: MITRE ATT&CK (tactics and techniques), VERIS (Vocabulary for Event Recording), CVSSv4 (for vulnerability-related incidents), Traffic Light Protocol (TLP) for information sharing, and national CERT classification schemes. Mappings enable standardised information exchange with external parties.",
      reason: "Ohne Kompatibilität mit externen Standards ist der Informationsaustausch mit CERTs, Behörden und Partnern erschwert. Standardisierte Mappings ermöglichen effiziente Kommunikation.",
      reasonEn: "Without compatibility with external standards, information exchange with CERTs, authorities, and partners is hampered. Standardised mappings enable efficient communication.",
      whenRequired: "Erforderlich für Organisationen, die mit CERTs und ISACs zusammenarbeiten.",
      whenRequiredEn: "Required for organisations collaborating with CERTs and ISACs.",
      sources: ["MITRE ATT&CK", "VERIS Framework", "NIS2 Art.29", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p33-c19", title: "Klassifizierung von Near-Misses und Schwachstellen", titleEn: "Classification of Near-Misses & Vulnerabilities",
      description: "Neben tatsächlichen Vorfällen müssen auch Near-Misses und gemeldete Schwachstellen in das Klassifizierungssystem integriert werden. Near-Misses erhalten eine separate Kategorie mit Bewertung des potenziellen Schadens. Schwachstellen werden nach CVSS-Score und organisationsspezifischer Relevanz bewertet. Die Integration ermöglicht eine ganzheitliche Sicht auf die Bedrohungslage.",
      descriptionEn: "In addition to actual incidents, near-misses and reported vulnerabilities must be integrated into the classification system. Near-misses receive a separate category with assessment of potential damage. Vulnerabilities are evaluated by CVSS score and organisation-specific relevance. Integration enables a holistic view of the threat landscape.",
      reason: "Near-Misses und Schwachstellen sind Vorstufen zu tatsächlichen Vorfällen. Ihre Integration in das Klassifizierungssystem ermöglicht proaktive Prävention.",
      reasonEn: "Near-misses and vulnerabilities are precursors to actual incidents. Their integration into the classification system enables proactive prevention.",
      whenRequired: "Empfohlen für eine ganzheitliche Sicherheitsbewertung.",
      whenRequiredEn: "Recommended for a holistic security assessment.",
      sources: ["ISO 27001:2022 A.8.8", "BSI IT-Grundschutz DER.2.1", "CVSSv4", "NIST CSF 2.0 DE.AE"] },

    { id: "p33-c20", title: "Analytische Priorisierungsmatrix für Gegenmaßnahmen", titleEn: "Analytical Prioritisation Matrix for Countermeasures",
      description: "Basierend auf der Klassifizierung muss eine analytische Priorisierungsmatrix die Dringlichkeit und Art der erforderlichen Gegenmaßnahmen bestimmen. Die Matrix kombiniert Schweregrad (p33-c00), betroffene Schutzziele (p33-c07), Compliance-Impact (p33-c15) und Wiederholungswahrscheinlichkeit (p33-c13) zu einer Gesamtpriorität. Für jede Prioritätsstufe müssen Mindest-Gegenmaßnahmen und maximale Umsetzungsfristen definiert sein. Die operative Umsetzung der Ressourcenzuweisung auf Basis dieser Matrix wird in p32-c11 geregelt.",
      descriptionEn: "Based on classification, an analytical prioritisation matrix must determine the urgency and type of required countermeasures. The matrix combines severity (p33-c00), affected protection goals (p33-c07), compliance impact (p33-c15), and recurrence probability (p33-c13) into an overall priority. For each priority level, minimum countermeasures and maximum implementation deadlines must be defined. The operational implementation of resource allocation based on this matrix is governed in p32-c11.",
      reason: "Diese Klausel definiert die analytische Logik der Priorisierung; p32-c11 setzt die daraus resultierende Ressourcenzuweisung operativ um.",
      reasonEn: "This clause defines the analytical logic of prioritisation; p32-c11 operationally implements the resulting resource allocation.",
      whenRequired: "Erforderlich als Brücke zwischen Klassifizierung und Maßnahmenumsetzung.",
      whenRequiredEn: "Required as a bridge between classification and countermeasure implementation.",
      sources: ["ISO 27001:2022 A.5.26", "NIST SP 800-61r3", "BSI IT-Grundschutz DER.2.1"] },

    { id: "p33-c21", title: "Dokumentation und Audit-Trail der Klassifizierung", titleEn: "Classification Documentation & Audit Trail",
      description: "Jede Klassifizierungsentscheidung muss mit Begründung, Zeitstempel und verantwortlichem Analysten dokumentiert werden. Änderungen an der Klassifizierung müssen einen vollständigen Audit-Trail aufweisen. Die Dokumentation muss für Audits, regulatorische Anfragen und interne Überprüfungen jederzeit zugänglich sein. Automatische Klassifizierungen durch SIEM/SOAR müssen ebenso dokumentiert werden wie manuelle Korrekturen.",
      descriptionEn: "Every classification decision must be documented with justification, timestamp, and responsible analyst. Changes to classification must have a complete audit trail. Documentation must be accessible at all times for audits, regulatory inquiries, and internal reviews. Automatic classifications by SIEM/SOAR must be documented as well as manual corrections.",
      reason: "Nachvollziehbare Klassifizierungsentscheidungen sind für Audits und regulatorische Compliance essentiell. Ohne Audit-Trail kann die Angemessenheit der Reaktion nicht nachgewiesen werden.",
      reasonEn: "Traceable classification decisions are essential for audits and regulatory compliance. Without an audit trail, the appropriateness of the response cannot be demonstrated.",
      whenRequired: "Immer erforderlich als Compliance-Anforderung.",
      whenRequiredEn: "Always required as a compliance requirement.",
      sources: ["ISO 27001:2022 A.5.33", "NIS2 Art.23(4)", "BSI IT-Grundschutz DER.2.1"] },

    // p33-c22 entfernt — Inhalt in p33-c16 zusammengeführt (Überprüfung und Aktualisierung des Klassifizierungssystems)
  ],
};
